window.SUBVERSION_CATALOGS = {"items":[{"id":"electronics","label":"Electronics & Software","items":[{"id":"paylo","name":"Paylo","cost":1,"summary":"Security Rating 8; Firewall 0.","description":"Security Rating 8; Firewall 0.","source":"Core Rules p. 99"},{"id":"personal-halo","name":"Personal Halo","cost":2,"summary":"Security Rating 12; Firewall 5.","description":"Security Rating 12; Firewall 5.","source":"Core Rules p. 99"},{"id":"halogram","name":"Halogram","cost":3,"summary":"Security Rating 16; Firewall 10.","description":"Security Rating 16; Firewall 10.","source":"Core Rules p. 100"},{"id":"graylo","name":"Graylo","cost":3,"summary":"Alternate digital identity; +4 Deception to use it. Security Rating 14; Firewall 10.","description":"Alternate digital identity; +4 Deception to use it. Security Rating 14; Firewall 10.","source":"Core Rules p. 100"},{"id":"long-distance-relay","name":"Long Distance Relay","cost":1,"summary":"Extends halo communications through a wired or satellite connection.","description":"Extends halo communications through a wired or satellite connection.","source":"Core Rules p. 100"},{"id":"remote-server","name":"Remote Server","cost":4,"summary":"+2 Science in Dramatic or Downtime scenes; those tasks take half the time. Security Rating 12; Firewall 15.","description":"+2 Science in Dramatic or Downtime scenes; those tasks take half the time. Security Rating 12; Firewall 15.","source":"Core Rules p. 100"},{"id":"universal-translator","name":"Universal Translator","cost":2,"summary":"Communicate in any common language, with -2 on social tests that rely on the translation.","description":"Communicate in any common language, with -2 on social tests that rely on the translation.","source":"Core Rules p. 101"},{"id":"artists-aids","name":"Artists' Aids","cost":2,"summary":"Arts tests gain Reliable 2; compositions take half the normal time.","description":"Arts tests gain Reliable 2; compositions take half the normal time.","source":"Core Rules p. 101"},{"id":"reference-library","name":"Reference Library","cost":4,"summary":"+1 die on Humanities tests in Dramatic or Downtime scenes.","description":"+1 die on Humanities tests in Dramatic or Downtime scenes.","source":"Core Rules p. 101"},{"id":"catalog-of-things","name":"Catalog of Things","cost":3,"summary":"Reliable 3 on Humanities tests to identify manufactured objects.","description":"Reliable 3 on Humanities tests to identify manufactured objects.","source":"Core Rules p. 101"},{"id":"species-identifier","name":"Species Identifier","cost":3,"summary":"Reliable 3 on Science tests to identify living creatures.","description":"Reliable 3 on Science tests to identify living creatures.","source":"Core Rules p. 101"},{"id":"digit-alter","name":"Digit-Alter","cost":2,"summary":"+2 Deception on tests to create forgeries.","description":"+2 Deception on tests to create forgeries.","source":"Core Rules p. 101"},{"id":"digital-presence","name":"Digital Presence","cost":2,"summary":"Inspired on Influence tests made remotely.","description":"Inspired on Influence tests made remotely.","source":"Core Rules p. 101"}]},{"id":"tools","label":"Tools, Science & Medicine","items":[{"id":"masterpiece-implement","name":"Masterpiece Implement","cost":5,"summary":"Arts tests using the implement are Inspired.","description":"Arts tests using the implement are Inspired.","source":"Core Rules p. 102"},{"id":"portable-laboratory","name":"Portable Laboratory","cost":2,"summary":"+1 on Science tests to analyze something directly inspected.","description":"+1 on Science tests to analyze something directly inspected.","source":"Core Rules p. 102"},{"id":"medkit","name":"Medkit","cost":4,"summary":"Restore 2d6 Health, or spend 1 Grit and make a Science test to heal the test result. A target benefits once per Downtime.","description":"Restore 2d6 Health, or spend 1 Grit and make a Science test to heal the test result. A target benefits once per Downtime.","source":"Core Rules p. 102","roll":{"diceNum":2,"diceSize":"d6","diceBonus":""}}]},{"id":"drugs","label":"Drugs","items":[{"id":"flow","name":"Flow","cost":1,"summary":"Reliable 3 on sustained-focus tests; two Dulled on unrelated Observation tests. Duration 12 hours.","description":"Reliable 3 on sustained-focus tests; two Dulled on unrelated Observation tests. Duration 12 hours.","source":"Core Rules p. 102"},{"id":"god-tears","name":"God Tears","cost":1,"summary":"Reliable 3 on Shinesight and Inspired on Magic Arts, but the user cannot stop Shinesight during the high.","description":"Reliable 3 on Shinesight and Inspired on Magic Arts, but the user cannot stop Shinesight during the high.","source":"Core Rules p. 103"},{"id":"king-mud","name":"King Mud","cost":2,"summary":"+5 Initiative, Augment 3 on Melee attacks, +1 Armor, and Adamant 3. Illicit 2.","description":"+5 Initiative, Augment 3 on Melee attacks, +1 Armor, and Adamant 3. Illicit 2.","source":"Core Rules p. 103","traits":"Illicit 2"},{"id":"nonchalance","name":"Nonchalance","cost":1,"summary":"Heal up to 5 Animity damage from traumatic or stressful events since the last sleep.","description":"Heal up to 5 Animity damage from traumatic or stressful events since the last sleep.","source":"Core Rules p. 103"},{"id":"remembrance","name":"Remembrance","cost":1,"summary":"+2 on Wit-linked tests; Failures become Dynamic Failures and other tasks are Dulled. Illicit 1.","description":"+2 on Wit-linked tests; Failures become Dynamic Failures and other tasks are Dulled. Illicit 1.","source":"Core Rules p. 103","traits":"Illicit 1"},{"id":"sacred-blue","name":"Sacred Blue","cost":1,"summary":"Adamant 10 and one instance of Dulled on all tests for one hour. Illicit 1.","description":"Adamant 10 and one instance of Dulled on all tests for one hour. Illicit 1.","source":"Core Rules p. 104","traits":"Illicit 1"}]},{"id":"magic","label":"Magical Gear","items":[{"id":"shalmu","name":"Shalmu","cost":4,"summary":"A sacred image that can remove all dissonance from one spell, then crumbles.","description":"A sacred image that can remove all dissonance from one spell, then crumbles.","source":"Core Rules p. 104","traits":"Single Use"},{"id":"tseru","name":"Tseru","cost":2,"summary":"Harmonize one matching bar of mana as a Free Action; the Tseru is then spent.","description":"Harmonize one matching bar of mana as a Free Action; the Tseru is then spent.","source":"Core Rules p. 104","traits":"Single Use"},{"id":"float-stone","name":"Float Stone","cost":1,"summary":"Negates nearly all weight of up to 500 kg after a TN 12 Magic Arts activation.","description":"Negates nearly all weight of up to 500 kg after a TN 12 Magic Arts activation.","source":"Core Rules p. 104"},{"id":"apotropaic-amulet","name":"Apotropaic Amulet","cost":4,"summary":"Interrupt: +5 Aegis against one effect; can dispel a spell that then fails to affect the wearer.","description":"Interrupt: +5 Aegis against one effect; can dispel a spell that then fails to affect the wearer.","source":"Core Rules p. 104","traits":"Single Use"},{"id":"salve-of-life","name":"Salve of Life","cost":1,"summary":"TN 12 Magic Arts: restore 8 Health. Expires after use or the next Downtime.","description":"TN 12 Magic Arts: restore 8 Health. Expires after use or the next Downtime.","source":"Core Rules p. 105","traits":"Single Use"},{"id":"mage-gun","name":"Mage Gun","cost":10,"summary":"50 m magical ranged weapon powered by attuned arcane charges; damage depends on the mana used.","description":"50 m magical ranged weapon powered by attuned arcane charges; damage depends on the mana used.","source":"Core Rules p. 105","skill":"Ranged Combat","range":"50m","traits":"Frightening 8"}]},{"id":"security","label":"Espionage & Security","items":[{"id":"auto-intruder","name":"Auto-Intruder","cost":3,"summary":"Reliable 3 on Physicality or Tech tests against physical locks; can provide Breach Power 5.","description":"Reliable 3 on Physicality or Tech tests against physical locks; can provide Breach Power 5.","source":"Core Rules p. 105"},{"id":"bug-sweeper","name":"Bug-Sweeper","cost":2,"summary":"+2 Tech or Observation to detect bugs; also functions as a jammer and contact EMP.","description":"+2 Tech or Observation to detect bugs; also functions as a jammer and contact EMP.","source":"Core Rules p. 105"},{"id":"disguise-kit","name":"Disguise Kit","cost":2,"summary":"+1 die on Deception tests involving a prepared disguise or hidden identity.","description":"+1 die on Deception tests involving a prepared disguise or hidden identity.","source":"Core Rules p. 106"},{"id":"elaborate-wardrobe","name":"Elaborate Wardrobe","cost":2,"summary":"+1d6 Influence after changing to fit the situation; prevents out-of-place penalties.","description":"+1d6 Influence after changing to fit the situation; prevents out-of-place penalties.","source":"Core Rules p. 106"},{"id":"micro-links","name":"Micro-Links","cost":2,"summary":"Twenty tiny cameras and microphones requiring TN 15 Observation or Tech to detect.","description":"Twenty tiny cameras and microphones requiring TN 15 Observation or Tech to detect.","source":"Core Rules p. 106"},{"id":"stealth-suit","name":"Stealth Suit","cost":4,"summary":"+1d6 on Physicality tests to act stealthily.","description":"+1d6 on Physicality tests to act stealthily.","source":"Core Rules p. 106"},{"id":"multi-modal-binoculars","name":"Multi-Modal Binoculars","cost":4,"summary":"+2 Observation against an actively surveilled target; ignore range penalties while visible.","description":"+2 Observation against an actively surveilled target; ignore range penalties while visible.","source":"Core Rules p. 106"}]},{"id":"survival","label":"Survival & Exploration","items":[{"id":"advanced-climbing-gear","name":"Advanced Climbing Gear","cost":2,"summary":"+4 on Physicality tests related to climbing.","description":"+4 on Physicality tests related to climbing.","source":"Core Rules p. 106"},{"id":"diving-gear","name":"Diving Gear","cost":2,"summary":"Dive to 300 m with environmental protection and Reliable 3 on Physicality tests to swim.","description":"Dive to 300 m with environmental protection and Reliable 3 on Physicality tests to swim.","source":"Core Rules p. 106"},{"id":"emergency-shelter","name":"Emergency Shelter","cost":2,"summary":"Inflatable, climate-controlled shelter for four with air and water systems lasting one week.","description":"Inflatable, climate-controlled shelter for four with air and water systems lasting one week.","source":"Core Rules p. 106"},{"id":"hazmat-suit","name":"Hazmat Suit","cost":2,"summary":"Twelve hours of oxygen plus protection and sensors for chemical, biological, and radiation hazards.","description":"Twelve hours of oxygen plus protection and sensors for chemical, biological, and radiation hazards.","source":"Core Rules p. 106"}]},{"id":"weapons","label":"Combat Gear - Weapons","items":[{"id":"knife","name":"Knife","cost":0,"summary":"Melee; 1d6 plus half Brawn damage; AP 1; Frightening 3.","description":"Melee; 1d6 plus half Brawn damage; AP 1; Frightening 3.","source":"Core Rules p. 108","skill":"Melee Combat","range":"T","damage":"1d6 + half Brawn","ap":1,"traits":"Frightening 3","roll":{"diceNum":1,"diceSize":"d6","diceBonus":"+floor(@bwn.value/2)"}},{"id":"club","name":"Club","cost":0,"summary":"Melee; 2d6 plus Brawn damage; Conspicuous.","description":"Melee; 2d6 plus Brawn damage; Conspicuous.","source":"Core Rules p. 108","skill":"Melee Combat","range":"T","damage":"2d6 + Brawn","traits":"Conspicuous","roll":{"diceNum":2,"diceSize":"d6","diceBonus":"+@bwn.value"}},{"id":"sword","name":"Sword","cost":2,"summary":"Melee; 3d6 plus Brawn damage; AP 1; Conspicuous; Frightening 5.","description":"Melee; 3d6 plus Brawn damage; AP 1; Conspicuous; Frightening 5.","source":"Core Rules p. 108","skill":"Melee Combat","range":"T","damage":"3d6 + Brawn","ap":1,"traits":"Conspicuous, Frightening 5","roll":{"diceNum":3,"diceSize":"d6","diceBonus":"+@bwn.value"}},{"id":"stun-baton","name":"Stun Baton","cost":2,"summary":"Melee; 3d6 Electrical damage; AP 2; Nonlethal; Illicit 1.","description":"Melee; 3d6 Electrical damage; AP 2; Nonlethal; Illicit 1.","source":"Core Rules p. 108","skill":"Melee Combat","range":"T","damage":"3d6 Electrical","ap":2,"traits":"Nonlethal, Illicit 1","roll":{"diceNum":3,"diceSize":"d6","diceBonus":""}},{"id":"taser","name":"Taser","cost":2,"summary":"Ranged 10 m; 2d6 Electrical damage; AP 2; Nonlethal.","description":"Ranged 10 m; 2d6 Electrical damage; AP 2; Nonlethal.","source":"Core Rules p. 108","skill":"Ranged Combat","range":"10m","damage":"2d6 Electrical","ap":2,"traits":"Nonlethal","roll":{"diceNum":2,"diceSize":"d6","diceBonus":""}},{"id":"pistol","name":"Pistol","cost":3,"summary":"Ranged 50 m; 3d6 damage; AP 1; Illicit 2; Frightening 6.","description":"Ranged 50 m; 3d6 damage; AP 1; Illicit 2; Frightening 6.","source":"Core Rules p. 108","skill":"Ranged Combat","range":"50m","damage":"3d6","ap":1,"traits":"Illicit 2, Frightening 6","roll":{"diceNum":3,"diceSize":"d6","diceBonus":""}},{"id":"rifle","name":"Rifle","cost":5,"summary":"Ranged 200 m; 5d6 damage; AP 2; Conspicuous; Illicit 3; Frightening 8.","description":"Ranged 200 m; 5d6 damage; AP 2; Conspicuous; Illicit 3; Frightening 8.","source":"Core Rules p. 108","skill":"Ranged Combat","range":"200m","damage":"5d6","ap":2,"traits":"Conspicuous, Illicit 3, Frightening 8","roll":{"diceNum":5,"diceSize":"d6","diceBonus":""}},{"id":"single-use-rocket-launcher","name":"Single Use Rocket Launcher","cost":8,"summary":"Ranged 30-1000 m; 10d6 damage; AP 5; Blast; Conspicuous; Single Use; Illicit 4; Frightening 10.","description":"Ranged 30-1000 m; 10d6 damage; AP 5; Blast; Conspicuous; Single Use; Illicit 4; Frightening 10.","source":"Core Rules p. 108","skill":"Ranged Combat","range":"30-1000m","damage":"10d6","ap":5,"traits":"Blast, Conspicuous, Single Use, Illicit 4, Frightening 10","roll":{"diceNum":10,"diceSize":"d6","diceBonus":""}}]},{"id":"armor","label":"Combat Gear - Armor","items":[{"id":"synthleather-clothing","name":"Synthleather Clothing","cost":2,"summary":"Armor 2.","description":"Armor 2.","source":"Core Rules p. 111","armor":2},{"id":"armored-clothing","name":"Armored Clothing","cost":5,"summary":"Armor 5; Disguised.","description":"Armor 5; Disguised.","source":"Core Rules p. 111","armor":5,"traits":"Disguised"},{"id":"body-armor","name":"Body Armor","cost":10,"summary":"Armor 10; -1 Guard; Conspicuous; Illicit 2.","description":"Armor 10; -1 Guard; Conspicuous; Illicit 2.","source":"Core Rules p. 111","armor":10,"traits":"Conspicuous, -1 Guard, Illicit 2"}]}],"abilities":[{"id":"background","label":"Background","items":[{"id":"background-pastoral-upbringing","name":"PASTORAL UPBRINGING","page":128,"cost":"10 Fortune","effect":"Requires Altaipheran Origin. You grew up in the great rural pastures and farms of the UYC or Altaiphera, and have a deep familiarity with livestock and other animals. Gain Reliable 3 on all Piloting tests involving riding animals, as well as Science tests about animal husbandry."},{"id":"background-hunter","name":"HUNTER","page":128,"cost":"10 Fortune","effect":"Requires Altaipheran Origin. If you were fortunate, you gained expertise with firearms learning to hunt in the forests near your home—if you were unfortunate you learned this skill in the War of Scars. You gain Reliable 2 on all Ranged Combat tests as well as physicality tests to remain stealthy in outdoor environments."},{"id":"background-adaptable-bearing","name":"ADAPTABLE BEARING","page":128,"cost":"10 Fortune","effect":"Requires Babylonian Origin. The only constant in Neo Babylon is change. You've learned to deal with the constant changes in dominant corporations, Ukkim power games, and waxing and waning social movements. Once per session, you may gain +1d6 on any Test."},{"id":"background-school-of-hard-knocks","name":"SCHOOL OF HARD KNOCKS","page":128,"cost":"10 Fortune","effect":"Requires Babylonian Origin and Lower. or Undercity Caste. You're used to getting in fights. You gain +1 Guard and Reliable 2 on all Melee Combat tests."},{"id":"background-the-business-of-business","name":"THE BUSINESS OF BUSINESS","page":128,"cost":"10 Fortune","effect":"Requires Babylonian Origin and Lower. Middle Caste or above. You grew up in the greatest center of commerce in the world, and learned to barter and negotiate as you learned to walk. Gain Reliable 2 on all Influence and Deception tests. Transactional Relations (see pg 125) cost 1 less Fortune for you (minimum 1)"},{"id":"background-quick-kin","name":"QUICK KIN","page":128,"cost":"10 Fortune","effect":"Requires Chaldani Origin. You were immersed in the Chaldani tradition of great extended families (both by blood and by choice—the distinction is weak in Acape Anya). The ever expanding social circle left you always ready to treat someone like family, an impression that makes it easier to fit it. Gain Reliable 2 on all Influence tests, and gain 2 Grit whenever you buy a new Relation."},{"id":"background-the-sea-calls","name":"THE SEA CALLS","page":128,"cost":"10 Fortune","effect":"Requires Chaldani Origin. For many Chaldani, the ocean is more than just a geographical feature—it's a part of their culture and identity. Gain Reliable 3 on all physicality tests to swim and Piloting tests on the water."},{"id":"background-the-family","name":"THE FAMILY","page":128,"cost":"10 Fortune","effect":"Requires Chaldani Origin. The extended (and not always literal) family structures of the Chaldani has fueled one of the most successful organized crime factions in the world, the Bravia. While most people of Chaldani heritage have little dealings with the Bravia, significantly more know someone in their family who does, and those connections let someone cash in when they need some help. When you are paying interest on a Debt Step 8. Choose Debt (pg 94), you may instead choose to owe a favor to a suitable Relation affiliated with the Bravia. You do not need to pay interest on that debt while you owe a favor, however you will be expected to repay the favor in the future (the expected repayment matches the size of the debt). If you fulfill the favor, the debt is removed—but if you fail, expect trouble as the Bravia makes an example of you. Only one such favor can be owed at a time."},{"id":"background-scholarly-focus","name":"SCHOLARLY FOCUS","page":129,"cost":"10 Fortune","effect":"Requires Churuqian Origin. Churuq culture places little focus on physical prowess, instead encouraging reading and learning. Gain Reliable 2 on two of Science, Humanities, or Tech Tests (choose which skills when selecting this ability)"},{"id":"background-prolific-pen-pal","name":"PROLIFIC PEN PAL","page":129,"cost":"10 Fortune","effect":"Requires Churuqian Origin. Correspondence is a crucial part of Churuqian culture, with many Churuqs maintaining networks of acquaintances across the world with whom they share their expertise and cultural experiences. Once per session, you can use this ability to gain +3 on any test to know something."},{"id":"background-inheritance-of-fae-arcana","name":"INHERITANCE OF FAE ARCANA","page":129,"cost":"10 Fortune","effect":"Requires De Broceliande Origin. Tales of fae magic are common among the people of Val Broceliande, though if there is more to it than myth and a handful of hedge magicians bilking tourists, the secrets are well hidden. Whether your family possesses some scraps of deeper knowledge, or you've simply learned about magic from listening to so many fanciful tales, you've garnered a deeper appreciation of magic. You gain Reliable 2 on all Magic Arts tests, and once per session you may spend 1 Grit before rolling a Magic Arts Test to make that roll Inspired."},{"id":"background-forest-dweller","name":"FOREST DWELLER","page":129,"cost":"10 Fortune","effect":"Requires De Broceliande Origin. More than just spending hours upon hours in the forests, you've developed a reverence for nature that inspires you. When in a forest, all of your rolls are Inspired. When you spend Grit to block or heal Animity damage in a forest, you heal 1 additional Animity."},{"id":"background-face-your-fears","name":"FACE YOUR FEARS","page":129,"cost":"10 Fortune","effect":"Requires Ghassulian Origin. Ghassulian culture places an emphasis on even mindedness and being mentally prepared to deal with adversity. Once per session, you may spend 1 Grit to block 5 Animity damage."},{"id":"background-holistic-education","name":"HOLISTIC EDUCATION","page":129,"cost":"10 Fortune","effect":"Requires Ghassulian Origin. In the Ghassulian tradition, the line between science, magic, and philosophy is weak, and education in one bleeds over to another. If a character is trained in Magic Arts, Humanities, or Science, they gain Reliable 2 on all skill tests to know things using those skills (but not for practical uses of the skills). If all of these skills are at Trained, instead gain Reliable 3 on all rolls to know things using those skills."},{"id":"background-survivor","name":"SURVIVOR","page":130,"cost":"10 Fortune","effect":"Requires Lower or Undercity Caste. Maybe it was the Fairy Wars, maybe it was a disaster, or maybe it was the just the grueling traumas of poverty, but you've taken all of what the world has thrown at you and kept ticking. Roll 1 additional die whenever you make a Grit Test (see \"Grit Tests\" on pg 25), and whenever you succeed on a Grit Test you heal 3 Animity damage."},{"id":"background-head-start","name":"HEAD START","page":130,"cost":"10 Fortune","effect":"Requires Upper Middle Caste or above. B ackg r o u n d Pa r a d i g ms You had every advantage growing up, and it enabled you to excel. Increase your maximum Grit by 2."},{"id":"background-good-reputation","name":"GOOD REPUTATION","page":130,"cost":"10 Fortune","effect":"You have a strong connection in your Community. You gain +1 Base Regard with your Community and all starting Relations."},{"id":"background-ideologue","name":"IDEOLOGUE","page":130,"cost":"10 Fortune","effect":"You have a strong conviction and deep connections to one of the ideological movements among the Envoys. Increase your Base Regard with your Ideology Faction by 3, and whenever your ideology Value is triggered, gain 1 Grit."},{"id":"background-joie-de-vivre","name":"JOIE DE VIVRE","page":130,"cost":"10 Fortune","effect":"Growing up, you learned to take your pleasures when you could get them and live in the moment, and frag the consequences. Whenever you indulge an Impulse, you gain one additional Grit and heal 2 Animity damage."},{"id":"background-fae-touched","name":"FAE-TOUCHED","page":130,"cost":"10 Fortune","effect":"Your character is fae-touched—a distinction whose origins are shrouded in the mystery of the fae, but provide some benefits. The character knows that any fae-touched creature it is aware of within 10m is fae-touched, and detects as fae-touched to any other fae-touched creature. Your character always knows the ambient level of mana and when they are in Seelie and Unseelie Zones (see \"Seelie and Unseelie Zones\" on pg 276)"},{"id":"background-shame-to-your-house","name":"SHAME TO YOUR HOUSE","page":130,"cost":"Drawback (+10 Fortune)","effect":"Requires Chaldani Origin. In Chaldani culture, your actions reflect on your entire family. Whenever you violate one of your Community Values or otherwise diminish the reputation of your family, you take 3 Animity damage. You continue to take 1 Animity damage each Downtime until you remedy the situation (GM discretion) or take a Downtime Action to smooth things over."},{"id":"background-intellectual-shut-in","name":"INTELLECTUAL SHUT-IN","page":130,"cost":"Drawback (+10 Fortune)","effect":"Requires Churuqian Origin. The Churuqian preference for intellectual pursuits over physical ones has led to you being particularly uncomfortable with physical tasks. You gain one additional instance of Dulled on all Physicality and Melee Combat tests."},{"id":"background-ghassulian-nihilism","name":"GHASSULIAN NIHILISM","page":130,"cost":"Drawback (+10 Fortune)","effect":"Requires Ghassulian Origin. \"All will die\" is a common Ghassulian epithet, deployed to indicate everything from \"I don't care\" to \"This person takes themselves too seriously.\" Many Ghassulians take this strain of nihilism to heart, and are perhaps a tad more accepting of what fate has in store for them. Decrease maximum Grit by 2, but increase maximum Animity by 2."},{"id":"background-babylonian-monoculture","name":"BABYLONIAN MONOCULTURE","page":130,"cost":"Drawback (+10 Fortune)","effect":"Requires Babylonian Origin. With all the culture and glamour of Neo Babylon, it's possible to lose perspective on the rest of the world. You start with only Common-Ur as a language, and gain one instance of Dulled on all Humanities tests to know about cultures outside of Neo Babylon."},{"id":"background-standoffish","name":"STANDOFFISH","page":130,"cost":"Drawback (+10 Fortune)","effect":"Requires Altaipheran. Altaipherans have a not entirely undeserved reputation for being insular and cold to strangers, preferring to wait for people to prove themselves by actions before warming up to them. Either by sharing this view, or simply lack of practice, you struggle in first encounters. Decrease the Regard of anyone you meet by 3 for your first time meeting them, and you may never make first impression tests."},{"id":"background-aloof","name":"ALOOF","page":131,"cost":"Drawback (+10 Fortune)","effect":"Requires De Broceliande Origin. De Broceliande cultural products are stereotypically utilitarian, and many people from Val Broceliande show an indifference to the art and culture of others, either through an honest lack of interest or a sense of superiority and disdain. Either way, you gain an instance of Dulled on all Humanities, Arts, and Influence tests when interacting with art, culture, or entertainment from a culture other than your own."},{"id":"background-outsider","name":"OUTSIDER","page":131,"cost":"Drawback (+10 Fortune)","effect":"Perhaps you're new, or perhaps you've never really fit in. In either case, you're less connected than most to your Community. Decrease your starting Regard with your Community by 3."},{"id":"background-inept","name":"INEPT","page":131,"cost":"Drawback (+10 Fortune)","effect":"You are particularly inept at a skill. You gain an additional instance of Dulled whenever you test that skill. If you are Untrained in the skill, you are not assumed to be able to accomplish basic tasks. Your unfamiliarity also impairs your ability to benefit or protect against other's uses of the skill—negative effects targeting you (such as attacks or opposed tests) gain Augment 3, while beneficial effects using the skill have half the normal effect."},{"id":"background-consummate-consumer","name":"CONSUMMATE CONSUMER","page":131,"cost":"Drawback (+10 Fortune)","effect":"Maybe the ad-tech on your Halo just had your number, maybe you're a tech enthusiast and early adopter, or maybe you just like shiny things. Whatever the cause, you're the ideal customer to the many varied corporations of Neo Babylon, always buying new things you don't really need. Any Downtime you don't purchase an object worth at least 3 Fortune, spend 1 Fortune (on something cool, glamorous, but ultimately not helpful)"},{"id":"background-poor-impulse-control","name":"POOR IMPULSE CONTROL","page":131,"cost":"Drawback (+10 Fortune)","effect":"You are particularly susceptible to your impulses. At the end of each Downtime, if you have not triggered an Impulse since the end of the last Downtime, take 3 Irresistible Animity damage."},{"id":"background-aversion-to-violence","name":"AVERSION TO VIOLENCE","page":131,"cost":"Drawback (+10 Fortune)","effect":"Due to some combination of your values and your experiences, you are ill-prepared for violent situations. You may not apply Adamant to violent situations, and you take 3 Irresistible Animity damage the first time you or an ally takes Health damage due to violence each scene."},{"id":"background-troublemaker","name":"TROUBLEMAKER","page":131,"cost":"Drawback (+10 Fortune)","effect":"You're a known problem with the authorities— you've gotten in trouble in the past, possibly even spending a chunk of time in the purgatorium. This has led you to be singled out by the authorities. Reduce your Regard with the Lawjacks (or other authority, if applicable) by 5."},{"id":"background-unreliable-assistive-tech","name":"UNRELIABLE ASSISTIVE TECH","page":131,"cost":"Drawback (+10 Fortune)","effect":"You rely on an assistive device to accomplish common daily tasks (e.g. a wheelchair to move around, assistive technology to see). While in most situations this enables you to function normally, your assistive device occasionally fails (either because it's in a non-accommodating environment, it is unreliable, or it has been damaged or stolen). In such a case, the GM or player may propose to trigger this Drawback following the rules for Impulses (see pg 27), paying 3 GM Grit or gaining 3 Grit as per normal, and suffering a downside or consequence appropriate to their assistive device. Note, this drawback only applies to assistive devices with a noticeable chance of failure—for most people cybertech clears this bar, though some sub-par cybertech or particularly difficult medical complications can cause cybertech to be unreliable and meet the threshold for this drawback. If you ever cease to need your assistive device, you may pay 10 Fortune to lose this drawback."}]},{"id":"relations","label":"Relations","items":[{"id":"relations-minor-relation","name":"MINOR RELATION","page":132,"cost":"2 Fortune","effect":"You have a relationship with someone that is either only marginally stronger than your overall Relation with the Community, or with someone who is less able to help you than the typical aid you can find in the Community. Pick one of the following options: ※ Big shot: Power 6 Regard 1. You know someone who can do a lot, and they take your calls—but not much more than that without convincing. ※ Personal Connection: Power 4 Regard 6. You know a typical member of the Community on a first name basis, which makes them easier to find and gives you a slight edge in asking for favors. Paradi g m s ※ Little Guy: Power 2, Regard 11. You have a strong relationship with someone of relatively modest skills, but they’re still willing to help you out from time to time. ※ Dependent: Power 1, Regard 15. You have someone only marginally able to help you out, but nonetheless who has a deep relationship with you. You may take this option as many times as you want, each time gaining a different minor Relation."},{"id":"relations-normal-relation","name":"NORMAL RELATION","page":132,"cost":"10 Fortune","effect":"You have a substantial relationship with someone that can provide you with substantial benefits in your work. Pick one of the following options: ※ Sponsor: Power 6 Regard 5. You know someone more competent than you who’s willing to do you some favors from time to time. ※ Friend: Power 4, Regard 10. You have a strong, capable friend you can rely on. ※ Sidekick: Power 2, Regard 15. You have a best friend, family member, or other who is willing to back you up against anything, even if their backing is only worth so much. You may take this option as many times as you want, each time gaining a different normal Relation."},{"id":"relations-major-relation","name":"MAJOR RELATION","page":132,"cost":"20 Fortune","effect":"You have a substantial relationship with someone that can provide you with substantial benefits in your work. Pick one of the following options: ※ Friend in High Places: Power 8 Regard 5. You have a VIP willing to extend minor favors to you. ※ Patron: Power 6 Regard 10. You have a mentor, family member, or other Relation more influential or powerful than you but nonetheless solidly in your corner. ※ Ally: Power 4, Regard 15. You have a competent friend or family member willing to help you however they can (as long as you don’t take advantage of them). You may take this option as many times as you want, each time gaining a different major Relation."}]},{"id":"community","label":"Community","items":[{"id":"community-minor-faction","name":"MINOR FACTION","page":134,"cost":"10 Fortune","effect":"You have a connection to an additional Faction that is either less powerful than your Community or that you have a substantially weaker connection too. You gain one of the following options as a Relation: ※ Indifferent Institution: Power 7 Regard 0. You have a tenous connection to a powerful Faction (A Regard zero Relation allows you to reliably contact them and use their ability, though getting substantial help may require convincing). ※ Known Group: Power 5 Regard 5. You have Rel at i o n Pa r a d i g ms modest connection to a group of similar power to your Community. ※ Friendly Club: Power 3, Regard 10. You have a strong connection to a minor Faction."},{"id":"community-major-faction","name":"MAJOR FACTION","page":134,"cost":"20 Fortune","effect":"You have a connection to an additional major Faction that plays a substantial role in your life. You gain one of the following options: ※ Helpful Benefactors: Power 6 Regard 5. You have a connection to a powerful Faction. ※ Friendly Group: Power 4, Regard 10 Relation. You have a strong connection to a modest Faction. ※ Devoted Followers: Power 2, Regard 15 Relation. You have a small group intensely devoted to you. Customizing Relations For simplicity and speed of creation, each Relation is given a standardized cost, Power, and Regard, however players may increase or decrease the cost of Relations by +1 Power for each 5 Fortune of cost and +1 Regard for each 2 points of Fortune (doubled for Fac- tions). Each Relation costs at least one Fortune, and starting Relations may not cost more than 20 Fortune. A player may choose to boost their player character's Regard with a Community Relation this way, though the Fortune cost to the Community counts towards the 20 Fortune limit."},{"id":"community-archive","name":"ARCHIVE","page":136,"cost":"10 Fortune","effect":"Your Community has a library or other source of records that document the local goings on, history, and other important information. All Humanities tests to know something about the Community gain Reliable 3. If a character takes a Downtime Action to look something up about the Community, they gain +2d6 on the roll."},{"id":"community-land-trust","name":"LAND TRUST","page":136,"cost":"10 Fortune","effect":"The Community has communal housing that it can provide to their Envoys or others who need it. For every 5 Regard you have with your Community, you decrease the cost of lifestyle maintenance by 1, to a minimum of 0 (see \"Maintain Lifestyle\" on pg 37)"},{"id":"community-performance-space","name":"PERFORMANCE SPACE","page":136,"cost":"10 Fortune","effect":"This is a resource where PCs and NPCs alike can promote, indulge, train, and share their artistic abilities and passions. Characters may spend 1 Downtime Action to make an Arts Test while performing here. Characters may also spend 1 Downtime Action to attend a performance. If a PC is performing, the TN for the Arts Test is 13. If they succeed, those performing and attending gain 4 Animity or 2 Grit (which can be increased by a Dynamic or Critical Success). On a Failure, no Grit or Animity is gained, and on a Dynamic Failure, all PCs involved lose 2 Animity and 1 Grit."},{"id":"community-ellu-eshirtu","name":"ELLU ESHIRTU","page":136,"cost":"10 Fortune","effect":"A place of pilgrimage where the gods are said to move more often and more clearly. Communities benefit from these sacred shrines due to pilgrims, but also spiritually. Pilgrims say the shrine grounds them and gives them courage to face the world. Spend 1 Downtime Action to visit the Ellu and gain 3 Adamant until the next Downtime."},{"id":"community-equipment","name":"EQUIPMENT","page":137,"cost":"10 Fortune","effect":"Your Community has a communal supply of gear. This might represent an armory, a motor pool, special communications equipment, or any material object you can think of. The gear is available based on the table below: Gear Cost Availability Available to everyone in <5 Fortune the Community Readily available for one 5-10 Fortune person at a time Available for one person 11-20 Fortune most of the time Available for one person for exceptionally 21+ Fortune important uses to the Community."},{"id":"community-spectacle-wonder","name":"SPECTACLE/WONDER","page":137,"cost":"10 Fortune","effect":"Some things in life are so beautiful, so awe-inspiring, that they demand recognition. This is such a place, and it is in your Community. Players and GM should describe what this spectacle or wonder is and why it is so fascinating. Players can spend time showing others around, increasing their love for it, and helping others fall in love with it as well. Spend 1 Downtime Action to recover 1 Grit and 4 Animity."},{"id":"community-den-of-iniquity","name":"DEN OF INIQUITY","page":137,"cost":"10 Fortune","effect":"If your Community has a den of iniquity, choose 1 type of indulgence and describe the Den of Iniquity. When you take the Indulge Impulse Downtime Action (see \"Indulge Impulse\" on pg 36) for an indulgence that matches the Den of Iniquity, you may spend a Fortune. If you do you gain 5 Grit and the GM gains 3 Grit. C."},{"id":"community-community-garden","name":"COMMUNITY GARDEN","page":137,"cost":"10 Fortune","effect":"You have a vegetable garden, small farm, or other source of food capable of covering some of your Community's food needs. For every 5 Regard you have with your Community, you decrease the cost of lifestyle maintenance by 1, to a minimum of zero (see \"Maintain Lifestyle\" on pg 37). Community Upgrades The following options are available to upgrade the Community:."},{"id":"community-upgrade-power","name":"UPGRADE POWER","page":137,"cost":"20 Fortune","effect":"Requires 10o Fortune spent on. Community paradigm total (excluding starting Fortune). Bit by bit, you’ve made your Community stronger and more notable. You increase the Power of your Community by one. This increases the Power of all Relations (both Community Relations and personal relations) tied to your Community. This may be taken multiple times, each time requiring 100 additional Fortune spent on the Community paradigm."},{"id":"community-upgrade-caste","name":"UPGRADE CASTE","page":137,"cost":"20 Fortune","effect":"Requires 10o Fortune spent on. Community paradigm total (excluding starting Fortune). You’ve built up the wealth, infrastructure, prevailing wages, and connections to slowly increase the standard of living in your Community. Each player may choose to increase their caste by one level (either now or in the future) by taking a debt (see pg 94) (gaining no Fortune from it, as the Fortune instead goes to increasing their standard of living). A given character may only benefit from this once per upgrade. This may be taken multiple times, each time requires 100 additional Fortune spent on the Community paradigm."}]},{"id":"brawler","label":"Brawler","items":[{"id":"brawler-reflexive-combat","name":"REFLEXIVE COMBAT","page":138,"cost":"10 Fortune","effect":"In the first Round of any cinematic, you may add +1d6 to combat tests while suffering –2 Guard."},{"id":"brawler-martial-arts","name":"MARTIAL ARTS","page":138,"cost":"10 Fortune","effect":"You know how to use your body as a weapon. Your unarmed attacks do 2d6 damage instead of 1d6."},{"id":"brawler-grappler","name":"GRAPPLER","page":138,"cost":"10 Fortune","effect":"You gain +1d6 on Melee Combat tests to grapple. A target grappled by you has an additional Consequence (including adding one instance of Dulled)"},{"id":"brawler-disarm","name":"DISARM","page":138,"cost":"10 Fortune","effect":"As a Main Action, make a Melee Combat test against the guard of a target in T range. On a Success, you may knock a held item (such as a tool or weapon) from their hands onto the ground. On a Dynamic Success you may instead take the item into your possession. On a Critical Success, you may take an additional Main Action to immediately use the stolen item."},{"id":"brawler-block","name":"BLOCK","page":138,"cost":"10 Fortune","effect":"Interrupt. When you are targeted by a Melee Attack test, you may spend 1 Grit to activate this ability. Roll a Melee Combat Test and replace your guard with the result of the test."},{"id":"brawler-riposte","name":"RIPOSTE","page":138,"cost":"10 Fortune","effect":"Interrupt. Requires Block and two other. Brawler paradigm abilities. When you use the Block ability, if your roll is greater than the attacker's guard you may spend 3 Grit to treat your roll as a Melee Attack against them, doing damage as normal."},{"id":"brawler-grunt","name":"GRUNT","page":139,"cost":"10 Fortune","effect":"When you spend Grit to block Health damage, each point of Grit blocks 2 points of Health damage."},{"id":"brawler-grunt-2","name":"GRUNT 2","page":139,"cost":"20 Fortune","effect":"Requires Grunt and two other brawler. paradigm abilities. When you spend Grit to block Health damage, each point of Grit blocks 4 points of Health damage."},{"id":"brawler-street-tough","name":"STREET TOUGH","page":139,"cost":"10 Fortune","effect":"Once per session, you may reduce incoming Health damage by 5."},{"id":"brawler-street-tough-2","name":"STREET TOUGH 2","page":139,"cost":"20 Fortune","effect":"Requires Street Tough. When you use the Street Tough ability, instead block incoming Health damage by 15."},{"id":"brawler-blooded-enforcer","name":"BLOODED ENFORCER","page":139,"cost":"20 Fortune","effect":"Requires Street Tough, Street Tough. 2, and 1 other Brawler paradigm ability. You may use the ability from Street Tough one additional time per session. When you use this ability, gain +1d6 on any Melee Combat test on your next turn."},{"id":"brawler-kneecap","name":"KNEECAP","page":139,"cost":"10 Fortune","effect":"When you make a Dynamic Success on a Melee Combat Test, apply a Consequence (including adding one instance of Dulled) to the target until they recieve healing. On a Critical Success, instead apply 2 Consequences."},{"id":"brawler-thug","name":"THUG","page":139,"cost":"20 Fortune","effect":"Requires three other Brawler. paradigm abilities. You give no thought to consequences, only respect. You may take 3 Irresistible damage before making a Melee Attack to gain +5 on the roll."},{"id":"brawler-punch-it","name":"PUNCH IT","page":139,"cost":"10 Fortune","effect":"Requires three other Brawler. paradigm abilities. Where possible, probable, or dramatically appropriate, and at GM’s discretion, you may take 5 Irresistible Health damage and make a Melee Attack in place of any other skill test."},{"id":"brawler-take-the-hit","name":"TAKE THE HIT","page":139,"cost":"10 Fortune","effect":"Interrupt. When an ally within 10m is targeted by an attack, you may spend 1 Grit to move between the attacker and the ally. The attack targets you instead."}]},{"id":"face","label":"Face","items":[{"id":"face-don-t-give-up","name":"DON’T GIVE UP","page":140,"cost":"10 Fortune","effect":"Main Action. Spend 1 Grit. Target Ally (not yourself) gains +2d6 and is Inspired on their next test."},{"id":"face-belonging-everywhere","name":"BELONGING EVERYWHERE","page":140,"cost":"10 Fortune","effect":"When you encounter an NPC for the first time, their Regard is improved by one. You start concealment tracks directed at you (including as part of a group you’re in) at +3 concealment when attempting to blend in using disguise or social infiltration."},{"id":"face-that-s-not-what-happened","name":"THAT’S NOT WHAT HAPPENED!","page":140,"cost":"10 Fortune","effect":"During each Downtime, you may reset a single Relation's Regard to their Base Regard once without taking a Downtime Action."},{"id":"face-stand-up","name":"STAND UP","page":140,"cost":"10 Fortune","effect":"Interrupt. When an ally would take Animity damage from an attack, you may take it instead. Gain 1 Pressure Point."},{"id":"face-i-can-see-through-you","name":"I CAN SEE THROUGH YOU","page":140,"cost":"10 Fortune","effect":"Interrupt. Use when you’ve rolled a Dynamic or Critical Success using any skill against an opponent’s Vigilance. Ask one of the following questions about the target. The GM must answer honestly. Gain 1 Pressure Point. ※ What is their current mood/Regard? ※ How could I help them? ※ What is their motivation? ※ How can they be hurt?"},{"id":"face-look-at-me","name":"LOOK AT ME!","page":140,"cost":"10 Fortune","effect":"Main Action. You know how to grab attention. Roll Deception versus target’s Vigilance. On a Success, the target takes a -5 penalty on any tests targeting someone other than you as long as you use a Backup Action each turn to continue distracting the target."},{"id":"face-i-know-a-gal","name":"I KNOW A GAL","page":140,"cost":"10 Fortune","effect":"You may spend 2 Fortune or 5 Grit at any time to reveal a previously undescribed minor Relation (see \"Relations\" on pg 132); you gain that Relation."},{"id":"face-warnings-and-rumors-of-warnings","name":"WARNINGS AND RUMORS OF WARNINGS","page":140,"cost":"10 Fortune","effect":"Each Downtime you may ask the GM for Rumors you've heard. Pick one topic you're interested in— gain a Rumor (see \"Rumor, Risk and Ruin\" on pg 251) related to that topic, as well as one additional unrelated Rumor chosen by the GM."},{"id":"face-charmer","name":"CHARMER","page":140,"cost":"10 Fortune","effect":"You gain 1 Pressure Point whenever you take the Charm action (see pg 43). All such rolls are Inspired."},{"id":"face-calm","name":"CALM","page":140,"cost":"10 Fortune","effect":"You get +1d6 on your Test when you take the De- escalate action (see pg 57). If you succeed you gain 1 Pressure Point."},{"id":"face-threat","name":"THREAT","page":140,"cost":"10 Fortune","effect":"You gain +1d6 when taking the Threaten action (pg 45). If you inflict Animity damage as part of a threat, increase the damage by 2."},{"id":"face-i-ll-get-us-in","name":"I’LL GET US IN","page":140,"cost":"10 Fortune","effect":"Requires 3 other Face paradigm abilities. Where possible, probable, or dramatically appropriate, and at GM’s discretion, you may take 5 Irrestible Animity damage and make an Influence or Deception test in place of any other skill test."},{"id":"face-look-at-these-eyes","name":"LOOK AT THESE EYES","page":140,"cost":"10 Fortune","effect":"On your first successful first impressions test in a scene you gain 2 Pressure Points."},{"id":"face-shake-it-off","name":"SHAKE IT OFF","page":140,"cost":"10 Fortune","effect":"Gain Adamant 2 against social situations."},{"id":"face-networking","name":"NETWORKING","page":141,"cost":"20 Fortune","effect":"Requires 3 other Face. paradigm abilities. You know lots of people. Gain 40 Fortune worth of Relations (see \"Relations\" on pg 132), and whenever you use Boost Relationship action (see pg 37), you may boost Base Regard by up to three points (spending Fortune as normal)"},{"id":"face-the-long-game","name":"THE LONG GAME","page":141,"cost":"20 Fortune","effect":"Requires Charmer. This ability can only be used outside of a cinematic, and can only be used once per scene. Roll an Influence or Deception Test versus target’s Vigilance. On a Success, you gain a special Pressure Point that isn’t lost until used and can only be used on this same target. You may have as many Pressure Points from this ability as the greater of your ranks in Deception or Influence."}]},{"id":"artist","label":"Artist","items":[{"id":"artist-fine-arts","name":"FINE ARTS","page":141,"cost":"10 Fortune","effect":"Gain +1d6 on all Influence and Deception tests in any environment restricted to Upper-Middle Class or higher, or that required at least 1 Fortune to get in."},{"id":"artist-gifted","name":"GIFTED","page":141,"cost":"10 Fortune","effect":"Once per session, spend 1 Grit while undertaking an artistic endeavor and make a TN 12 Arts test. On a Success restore 3 Grit to an ally."},{"id":"artist-inspire","name":"INSPIRE","page":141,"cost":"10 Fortune","effect":"You can inspire people to help restore their Animity. Make a TN 12 Arts test, restoring 5 Animity damage on a Success. A character can only benefit from Inspire once per Session."},{"id":"artist-popular-culture","name":"POPULAR CULTURE","page":141,"cost":"10 Fortune","effect":"Gain +1d6 to Influence tests with individuals from Lower-Middle Caste or lower."},{"id":"artist-point-of-interest","name":"POINT OF INTEREST","page":141,"cost":"10 Fortune","effect":"You’ve created something that others love to appreciate. As a result, your Community has become known for your work. Once per Downtime, you can use a Downtime Action to give a tour, discuss art with fans, or teach others the basics of your art. You gain 1 Fortune and the Fortune cost for a Community paradigm ability is decreased by 2 until the start of the next Downtime."},{"id":"artist-chosen-family","name":"CHOSEN FAMILY","page":142,"cost":"10 Fortune","effect":"While many see artists as singularly reclusive and anti-social, the truth is many find solace in collectives or practice art together in a troupe or community. When you take the same Downtime Action as another PC, you both heal 2 Animity damage."},{"id":"artist-imitator","name":"IMITATOR","page":142,"cost":"10 Fortune","effect":"You may use Arts instead of Deception when making physical forgeries or disguises."},{"id":"artist-catharsis","name":"CATHARSIS","page":142,"cost":"20 Fortune","effect":"Requires Gifted. Art of all forms does not just inspire and distract, but brings itself to a place where the audience comes away relieved and refreshed. You help people through that emotional journey. You may use the gifted ability twice per session, and using it does not require Grit."},{"id":"artist-create-shalmu","name":"CREATE SHALMU","page":142,"cost":"10 Fortune","effect":"You use your incredible skill to attempt to create a shalmu, or an image, of one of the divine powers. (see \"Shalmu\" on pg 104). In order to create a shalmu, you must have a sacred mantle or join with someone who does. If you have a sacred mantle yourself, you must spend a Downtime Action and succeed on a TN 12 Arts Test. If you do not have a sacred mantle, you and someone who does have a sacred mantle may both give up a Downtime Action, and you must succeed on a TN 12 Arts Test, and the other person must succeed on a TN 12 Magic Arts Test."}]},{"id":"delver","label":"Delver","items":[{"id":"delver-delver-s-awareness","name":"DELVER’S AWARENESS","page":142,"cost":"10 Fortune","effect":"When you spend a Grit to re-roll a die on an Observation test, you may re-roll any dice and your roll becomes Inspired."},{"id":"delver-let-me-help-you-with-that","name":"LET ME HELP YOU WITH THAT","page":142,"cost":"10 Fortune","effect":"Whenever you succeed on a Group Test (see pg 20), all allies gain Reliable 3 on that Test."},{"id":"delver-danger-sense","name":"DANGER SENSE","page":142,"cost":"10 Fortune","effect":"Interrupt. On the first Round of a cinematic, or outside of a cinematic when you are surprised by something targeting you, you may spend 1 Grit to gain +4 Guard, Aegis, or Vigilance."},{"id":"delver-by-whip-or-shovel","name":"BY WHIP OR SHOVEL","page":142,"cost":"10 Fortune","effect":"Choose a non-weapon object. You may use that object in combat as if it were a melee weapon dealing 2d6 damage in T range with the nonlethal quality. Additionally, choose one of the following when purchasing this paradigm: on a Dynamic or Critical Success the target is grappled, or add Brawn to Damage."},{"id":"delver-watch-it","name":"WATCH IT!","page":143,"cost":"10 Fortune","effect":"Spend 1 Grit to replace an ally’s defense or roll with one of your own when avoiding a hidden attack or trap."},{"id":"delver-scouting-ahead","name":"SCOUTING AHEAD","page":143,"cost":"10 Fortune","effect":"When you succeed on a Prepare for Trouble Downtime Action (see \"Prepare for Trouble\" on pg 37), everyone in your team gains 1 temporary Grit to spend on the next scene. When you are traveling and not in a cinematic you may spend 3 Grit to take the Prepare for Trouble Action."},{"id":"delver-ready-for-anything","name":"READY FOR ANYTHING","page":143,"cost":"20 Fortune","effect":"Requires 3 other Delver paradigm. abilities Proper prior planning is part of your daily routine. You have drilled what to do in the case of an emergency. At any time outside of a cinematic, you may spend 1 Grit to re-roll any number of dice on your last roll. Gain Reliable 2 on all dice rerolled this way. You can also use this ability to force a re-roll of an action targeting you. At any time outside a cinematic, you may spend 3 Grit to force a re-roll on a Test targeting you or your allies."},{"id":"delver-you-can-t-surprise-a-delver","name":"YOU CAN’T SURPRISE A DELVER","page":143,"cost":"20 Fortune","effect":"Requires Danger Sense and 3 other. Delver paradigm abilities If a roll against your Vigilance would still succeed after using Danger Sense, spend 1 Grit to add 5 to your Vigilance."},{"id":"delver-mysterious-encounter","name":"MYSTERIOUS ENCOUNTER","page":143,"cost":"20 Fortune","effect":"Requires 3 other Delver. paradigm abilities. You touched something once, or saw a strange creature… and it left something behind, intuition. You have an innate sense for obscure artifacts and treasures. You gain Inspired and Reliable 3 on all tests dealing with any magical artifacts or ruins more than 100 years old."},{"id":"delver-go-left-for-treasure","name":"GO LEFT FOR TREASURE","page":143,"cost":"20 Fortune","effect":"Requires 3 other Delver. paradigm abilities. You have a sense for the patterns of places. Gain +2d6 and Reliable 3 on all Science and Observation tests related to architecture or structures."}]},{"id":"magic-hunter","label":"Magic Hunter","items":[{"id":"magic-hunter-magic-in-theory","name":"MAGIC, IN THEORY","page":143,"cost":"10 Fortune","effect":"Gain a bonus equal to your ranks in Magic Arts plus one on all Magic Arts tests related to identifying a magical creature, spell, or effect, or on any tests to know anything about the theoretical basis of magic."},{"id":"magic-hunter-mundane-countermeasures","name":"MUNDANE COUNTERMEASURES","page":144,"cost":"10 Fortune","effect":"You understand how magic works, and crucially, how to prevent it from working well. Gain a bonus to Aegis equal to one plus your ranks in Magic Arts."},{"id":"magic-hunter-understand-the-patterns-of-magic","name":"UNDERSTAND THE PATTERNS OF MAGIC","page":144,"cost":"10 Fortune","effect":"You gain Reliable 3 on all Shine Perception tests Shine Perception (pg 61). Reduce the TN to spot magical effects with an Observation test by your ranks in Magic Arts plus one."},{"id":"magic-hunter-break-the-flow-of-magic","name":"BREAK THE FLOW OF MAGIC","page":144,"cost":"10 Fortune","effect":"Through careful study, you’ve learned the process others use to channel magic, and have learned how to distract casters when you take actions against them in a way to disrupt their magical abilities. When you inflict damage (either Health or Animity) you may spend one Grit for one of the following effects, as appropriate to their magical type: ※ Increase any dissonance from a recently cast spell by one ※ Negate one bar of harmonized mana ※ Negate the effects of all meditations until the end of your next turn ※ Give a temporary Consequence to a spirit or magical creature that lasts for one hour."},{"id":"magic-hunter-understand-creatures-of-magic","name":"UNDERSTAND CREATURES OF MAGIC","page":144,"cost":"10 Fortune","effect":"You gain Reliable 3 on all Influence and Deception tests against spirits or other magical creatures."},{"id":"magic-hunter-a-mind-apart-from-magic","name":"A MIND APART FROM MAGIC","page":144,"cost":"10 Fortune","effect":"You gain Adamant 4 against all magical effects."},{"id":"magic-hunter-mana-breaker","name":"MANA BREAKER","page":144,"cost":"20 Fortune","effect":"Requires Break the Flow of Magic and. 2 other Magic Hunter paradigm abilities. On a Dynamic or Critical Success when you use Break the Flow of Magic, you may additionally pick the following effect, as appropriate to their magical type: ※ All unattuned dissonance is immediately taken as Animity damage as if they had failed to take the attuning action on their turn. ※ All bars of harmonized mana are lost and the caster takes 1 Irresistible Health damage per harmonized bar of mana. ※ One meditation is ended. ※ Give a Consequence to a spirit or magical creature (this Consequence is healed normally)"},{"id":"magic-hunter-elude-magic","name":"ELUDE MAGIC","page":144,"cost":"20 Fortune","effect":"Requires Mundane Countermeasures. and 2 other Magic Hunter paradigm abilities. After learning the result of a roll that targets your Aegis, you may spend 1 Grit to increase your Aegis by 5."},{"id":"magic-hunter-negate-magical-effect","name":"NEGATE MAGICAL EFFECT","page":144,"cost":"20 Fortune","effect":"Requires Mundane Countermeasures. and 2 other Magic Hunter paradigm abilities. You have learned a number of techniques to allow yourself and others another chance to resist magical effects, either by taking advantage of the limitations of magic or helping others directly resist its effects through mundane means. You may make a Magic Arts test as a Main Action to end an ongoing effect that targeted Aegis. Make an opposed test against the skill or entity that caused the effect. If you succeed, any ongoing effects from that ability end (this does not apply to damage the effect has already done)"},{"id":"magic-hunter-disrupt-magical-soul","name":"DISRUPT MAGICAL SOUL","page":144,"cost":"30 Fortune","effect":"Requires Mana Breaker and 5 other. Magic Hunter paradigm abilities. Your studies of how magical practitioners and creatures use magic has progressed to the degree that you have learned how to inflict wounds that disrupt their ability to channel mana until they have the chance to recover. On a Critical Success when you use Break the Flow of Magic they lose the ability to use any magical abilities (such as from a magical paradigm or the special abilities of a spirit or magical creature) for the next hour. Additionally, make a Magic Arts test against the target's Aegis. On a Dynamic Success on this test, the effect lasts until they next take the rest up action. On a Critical Success, the target instead gains a Downtime Progress Track with 20 progress on it. The character is unable to use magic until the Progress Track is reduced to zero."}]},{"id":"researcher","label":"Researcher","items":[{"id":"researcher-archive-sphinx","name":"ARCHIVE SPHINX","page":145,"cost":"10 Fortune","effect":"Your time working in Archives has helped you not only make connections but build one of your own, no matter how modest. When you use an archive resource as a Downtime Action (see \"Archive\" on pg 136), your roll gains Inspired and you gain 2 Grit."},{"id":"researcher-well-versed","name":"WELL VERSED","page":145,"cost":"10 Fortune","effect":"When you spend a Grit to re-roll a die on a Humanities or Sciences test, you may re-roll any dice, and your roll becomes Inspired."},{"id":"researcher-linguistic-practice","name":"LINGUISTIC PRACTICE","page":145,"cost":"10 Fortune","effect":"You gain one extra language, plus one for each rank in Humanities you have."},{"id":"researcher-methodical-research","name":"METHODICAL RESEARCH","page":145,"cost":"10 Fortune","effect":"When you prepare for trouble (see pg 37) using Humanities or Science, you reduce the GM Grit by an additional 1 point and shift a Progress Track by an additional 3 points."},{"id":"researcher-kept-my-notes","name":"KEPT MY NOTES","page":145,"cost":"10 Fortune","effect":"Choose either Humanities or Sciences. Gain Reliable 3 when using that skill outside of cinematic time."},{"id":"researcher-truths-and-myths","name":"TRUTHS AND MYTHS","page":145,"cost":"20 Fortune","effect":"Requires 3 other Researcher. paradigm abilities. You may roll Humanities instead of Magic Arts for any test related to knowing about magic or magical creatures. Increase your Aegis by 2."},{"id":"researcher-propaganda-comes-in-one-size","name":"PROPAGANDA COMES IN ONE SIZE","page":145,"cost":"20 Fortune","effect":"Requires 3 other Researcher. paradigm abilities. Deception tests against you take a -5 penalty."},{"id":"researcher-patterns-of-behavior","name":"PATTERNS OF BEHAVIOR","page":145,"cost":"20 Fortune","effect":"Requires 3 other Researcher. paradigm abilities. When you gain a Dynamic or Critical Success on a Humanities Test to learn something about a target, you gain an insight into their actions or weaknesses that you may use later. Once before the next Downtime, you may spend 1 Grit to add or subtract 5 to a Test they make or a Test targeting them."}]},{"id":"mastermind","label":"Mastermind","items":[{"id":"mastermind-aware-of-the-situation","name":"AWARE OF THE SITUATION","page":146,"cost":"10 Fortune","effect":"You never spend Grit to act in the Surprise Round."},{"id":"mastermind-plan-b","name":"PLAN B","page":146,"cost":"10 Fortune","effect":"After you or an ally fails a skill Test, you may spend 1 Grit to ignore any complication preventing them from trying again. If you do so, you may suggest another way to handle the situation as a Main Action. Specify a skill and a course of action. The next PC that attempts to use the specified skill to work towards the specified course of action gains Reliable 3 on the roll."},{"id":"mastermind-community-planner","name":"COMMUNITY PLANNER","page":146,"cost":"10 Fortune","effect":"You and any allies gain Augment 3 on any projects to make a Community resource (see \"Advance Downtime Track\" on pg 36)"},{"id":"mastermind-two-moves-ahead","name":"TWO MOVES AHEAD","page":146,"cost":"10 Fortune","effect":"Interrupt. You may spend 1 Grit to increase your initiative score by +5 for the rest of the cinematic."},{"id":"mastermind-three-moves-ahead","name":"THREE MOVES AHEAD","page":146,"cost":"20 Fortune","effect":"Interrupt. Requires Two Moves Ahead. and 2 other Mastermind paradigm abilities. On the first Round of a cinematic, you may spend 5 Grit to take an additional Main Action as a Backup Action."},{"id":"mastermind-careful-maneuvering","name":"CAREFUL MANEUVERING","page":146,"cost":"10 Fortune","effect":"You always plan your moves with great care, for the greatest effect or efficiency. Whenever you take an action to move (Main or Backup Action), you may take the Defend action as a Free Action. This does not allow you to take another Defend Action, even if you have extra Backup Actions available."},{"id":"mastermind-team-player","name":"TEAM PLAYER","page":146,"cost":"10 Fortune","effect":"Whenever you take a Main Action to assist an ally (either by using teamwork or taking a beneficial action that targets them), you may take an additional Backup Action. You may use the Focus or Aim Backup Action to provide a bonus to an ally’s skill Test instead of your own (up to the normal maximum bonus from Focus/Aim)"},{"id":"mastermind-they-never-see-it-coming","name":"THEY NEVER SEE IT COMING","page":146,"cost":"20 Fortune","effect":"Your careful planning and talent for misdirection make it easy to blindside someone. It costs twice as much Grit for enemies to act in a Surprise Round you initiated. At the beginning of a stealth encounter, you may spend Grit to increase your initial concealment at a cost of 1 Grit per 2 concealment (up to a maximum starting concealment of 20)"},{"id":"mastermind-informants","name":"INFORMANTS","page":147,"cost":"20 Fortune","effect":"Requires 3 other Mastermind. paradigm abilities. You have cultivated a network of local informants who gather gossip and spy on people for you. You may spend 1 Grit at any time to gain a relevant rumor about a topic of your choice (if no helpful rumors are available, you spend no Grit). If you also have the That’s Always Been the Plan paradigm ability, once per session you may use the Reinforcements benefit for zero Grit or Fortune cost."},{"id":"mastermind-that-s-always-been-the-plan","name":"THAT’S ALWAYS BEEN THE PLAN","page":147,"cost":"20 Fortune","effect":"Requires 3 other Mastermind. paradigm abilities. Once per session, you may use a Backup Action and spend 1 Grit to benefit from your careful and timely preparations. You must describe a brief flashback scene that reveals how you prepared for this eventuality. ※ Acquire an item: You managed to smuggle in just the right piece of equipment for this situation! Choose an item. That item is now in your possession (and has been all along). If you do not already own the item, you must pay its Fortune cost immediately. If the item has no Fortune cost, you must either pay 1 Fortune or 1 additional Grit for it. ※ Make previous arrangements with an individual: You made sure to butter up an NPC in a previously undeclared encounter. Improve an NPC’s Regard track towards you by five. If you are in a stealth encounter, you may use this to increase your team’s current Concealment level by 1d6 (2d6 with a Critical Success). ※ Reinforcements: You made sure you had backup ready, just in case something like this happened. Choose an NPC that has a Favored (or better) Regard towards you. Pay either 1 Grit or 1 Fortune to have that NPC show up immediately and take one Main Action on your behalf. The NPC will stick around and help until the end of the conflict or scene."}]},{"id":"rouser","label":"Rouser","items":[{"id":"rouser-passionate-confidence","name":"PASSIONATE CONFIDENCE","page":147,"cost":"10 Fortune","effect":"In the first Round of any cinematic, you may add +1d6 to Influence or Deception tests while suffering –3 Vigilance."},{"id":"rouser-tune-it-out","name":"TUNE IT OUT","page":148,"cost":"10 Fortune","effect":"Interrupt. You may spend 1 Grit to block 2 Animity damage targeting another character."},{"id":"rouser-determined-mind","name":"DETERMINED MIND","page":148,"cost":"10 Fortune","effect":"Once per session, you may reduce incoming Animity damage by 5."},{"id":"rouser-soothe","name":"SOOTHE","page":148,"cost":"10 Fortune","effect":"Main Action. Make a TN 12 Influence test, on a Success, restore 3 Animity damage. A character can only benefit from Soothe once per session."},{"id":"rouser-rouse","name":"ROUSE","page":148,"cost":"10 Fortune","effect":"Main Action. Make a TN 12 Influence test, on a Success, each ally gains +1 die to their next action. Multiple uses do not stack. Using this outside of a cinematic costs 1 Grit."},{"id":"rouser-confuse","name":"CONFUSE","page":148,"cost":"10 Fortune","effect":"Main Action. Make an Influence or Deception Test against a target’s Vigilance. On a Success, deal 1 Animity damage. On a Dynamic Success, target gains a Consequence until the damage is healed or the end of the scene (whichever happens first). On a Critical Success, the target gains 2 Consequences."},{"id":"rouser-no-shame","name":"NO SHAME","page":148,"cost":"10 Fortune","effect":"Interrupt. When you make a successful Influence or Deception test, you may take 5 Irresistible Animity damage to give that test Augment 5."},{"id":"rouser-stir-shet-up","name":"STIR SHET UP","page":148,"cost":"10 Fortune","effect":"Main Action. Once per session per target, you may make an Influence test against a targets Vigilance. On a Success, lower the target’s Regard for one character by 5."},{"id":"rouser-clarion-call","name":"CLARION CALL","page":148,"cost":"20 Fortune","effect":"Requires 2 other Rouser. paradigm abilities. Spend 3 Grit to make any roll against a target’s Vigilance into a roll against all targets within 50m. Use the highest Vigilance among the crowd to determine success. Note: If combined with Pressure Points from the Face paradigm, spending Pressure Points lowers the Vigilance of the entire crowd."}]},{"id":"militaire","label":"Militaire","items":[{"id":"militaire-push-on","name":"PUSH ON","page":148,"cost":"10 Fortune","effect":"It costs one Grit instead of four to ignore all Dulled penalties for any roll linked to Agility or Brawn."},{"id":"militaire-physical-conditioning","name":"PHYSICAL CONDITIONING","page":148,"cost":"10 Fortune","effect":"Increase your max Speed to 2."},{"id":"militaire-squad-tactics","name":"SQUAD TACTICS","page":148,"cost":"10 Fortune","effect":"You may spend a Backup Action to coordinate the actions of yourself and a number of allies up to your Wits. This provides a +1 bonus to all Melee and Ranged attacks made by any affected character until after your next turn. If you make an attack against an opponent that one of your allies has previously attacked this Round, gain +1 die on your own attack Test."},{"id":"militaire-move-move-move","name":"MOVE! MOVE! MOVE!","page":149,"cost":"10 Fortune","effect":"You gain +1d6 on Physicality tests in chases. Once per Round you may spend 1 Grit to take the Minor Move action as a Free Action."},{"id":"militaire-no-guts-no-glory","name":"NO GUTS, NO GLORY!","page":149,"cost":"10 Fortune","effect":"When you spend a Backup Action to use Focus or Aim on a combat roll, you may increase the bonus by +1 for every –1 that is applied to all of your defenses (up to your maximum bonus from Focus or Aim)"},{"id":"militaire-commanding-presence","name":"COMMANDING PRESENCE","page":149,"cost":"10 Fortune","effect":"Gain +1 die on Influence tests when you clearly and directly tell someone to do something. Gain a +2 bonus to Deception tests made against guards, law enforcement, and military personnel."},{"id":"militaire-pharmaceutical-advantage","name":"PHARMACEUTICAL ADVANTAGE","page":149,"cost":"10 Fortune","effect":"You were trained to go into combat under the influence of combat stimulants such as King Mud (pg 103). You gain +5 Vigilance on all addiction tests against combat stimulants, and you may spend 1 Grit to ignore any behavioral triggers from such drug (such as King Mud's trigger to avoid retreat)"},{"id":"militaire-pharmaceutical-honing","name":"PHARMACEUTICAL HONING","page":149,"cost":"20 Fortune","effect":"Requires Pharmaceutical Advantage. and 2 other Militaire paradigm abilities. You not only are trained to resist the psychological effects of combat drugs, but also to take advantage of their physiological effects to the utmost. Whenever you’re under the influence of a combat drug (e.g. King Mud), you gain +2 Guard, and all combat rolls you make are Inspired."},{"id":"militaire-combat-reflexes","name":"COMBAT REFLEXES","page":149,"cost":"10 Fortune","effect":"Gain +1 Guard. Reduce the Grit cost to act in the Surprise Round by 1."},{"id":"militaire-take-cover","name":"TAKE COVER!","page":149,"cost":"20 Fortune","effect":"Requires Combat Reflexes and 2 other. Militaire paradigm abilities. When you use a Backup Action to Defend, the bonus applies to all of your defenses. Additionally, you may still benefit from Dynamic and Critical Successes."}]},{"id":"medico","label":"Medico","items":[{"id":"medico-i-ve-seen-too-much","name":"I’VE SEEN TOO MUCH","page":149,"cost":"10 Fortune","effect":"Gain Adamant 5: Death, Blood, Weapons MEDICO There's far more wonder and mystery in biology than in magic—every cell, every tissue, every organism holds more mysteries than you can find in any mystic tome. —Gadja Shakanaki, Physician The Medico paradigm covers anyone with medical experience or training, be it a doctor, medic, veterinarian, or therapist. Taking any abilities from the Medico paradigm requires being trained in the Sciences skill."},{"id":"medico-first-aid","name":"FIRST AID","page":149,"cost":"10 Fortune","effect":"You gain Reliable 3 on Science tests while using a Medkit."},{"id":"medico-prophylactic-care","name":"PROPHYLACTIC CARE","page":149,"cost":"10 Fortune","effect":"Main Action. You may spend 1 Grit to provide protection against one metabolic or otherwise biological threat or danger (such as a poison, disease, hypoxia, or hyperthermia, but not physical damaging attacks). Make a TN 10 Science test. On a Success, the target gains +2 Guard, Vigilance, Aegis, and Armor against that threat for the next hour."},{"id":"medico-mental-health-professional","name":"MENTAL HEALTH PROFESSIONAL","page":149,"cost":"10 Fortune","effect":"When you use the Aid Recovery Downtime Action (see \"Aid Recovery\" on pg 36) you may heal any combination of Health and Animity with a successful Science Test."},{"id":"medico-surgery","name":"SURGERY","page":149,"cost":"10 Fortune","effect":"When you take the Aid Recovery Downtime Action (see \"Aid Recovery\" on pg 36) you may increase the TN by 3. If you do and succeed on the test they remove a Consequence in addition to the normal effects of the roll."},{"id":"medico-biologist","name":"BIOLOGIST","page":150,"cost":"10 Fortune","effect":"Your understanding of Medicine comes with a deep understanding of biology. Gain Reliable 3 on all Science tests to know things about biology or medicine (including diagnoses)"},{"id":"medico-bedside-manner","name":"BEDSIDE MANNER","page":150,"cost":"10 Fortune","effect":"You gain Reliable 3 on all social tests with anyone you have provided medical care to, or to convince someone who needs medical care to let you provide it to them."},{"id":"medico-improvised-care","name":"IMPROVISED CARE","page":150,"cost":"10 Fortune","effect":"Medkits cost 1 Fortune for you. You may spend 1 Grit to gain the benefits of a Medkit even if you don't have one."},{"id":"medico-late-night-calls","name":"LATE NIGHT CALLS","page":150,"cost":"10 Fortune","effect":"When you use your medical skills as part of the Side Gig action (see \"Side Gig\" on pg 37) the GM does not gain Grit, and you may spend 1 Fortune to increase the Base Regard of a non-Faction Relation by 1 as part of the action."},{"id":"medico-emergency-care","name":"EMERGENCY CARE","page":150,"cost":"10 Fortune","effect":"Requires First Aid. You do not need to spend a Grit when making a Science Test as part of using a Medkit. If you do spend a Grit, increase the amount healed by 3."},{"id":"medico-resuscitate","name":"RESUSCITATE","page":150,"cost":"20 Fortune","effect":"Requires Emergency Care and Surgery. You are capable of keeping people alive in even the most grievous of situations. When you apply first aid to treat a wound that caused a Consequence and the target has more than one Consequence, the target loses a Consequence."}]},{"id":"engineer","label":"Engineer","items":[{"id":"engineer-special-modifications","name":"SPECIAL MODIFICATIONS","page":150,"cost":"10 Fortune","effect":"When you use the project option to build or modify a piece of gear with enhancements (see \"Advance Downtime Track\" on pg 36), you may add one additional enhancement (pay Fortune normally). If you begin the game with this ability, you may apply it to a number of vehicles or items of gear equal to your ranks in Tech +1."},{"id":"engineer-infrastructure-specialist","name":"INFRASTRUCTURE SPECIALIST","page":150,"cost":"10 Fortune","effect":"When you make a Community Resource (see \"Resources\" on pg 136) as a project (see \"Advance Downtime Track\" on pg 36), you pay one fifth the normal cost (instead of half)"},{"id":"engineer-maker","name":"MAKER","page":150,"cost":"10 Fortune","effect":"You gain Augment 3 on all Tech tests to build or repair objects."},{"id":"engineer-practical-knowledge","name":"PRACTICAL KNOWLEDGE","page":150,"cost":"10 Fortune","effect":"You may roll Tech instead of Science for any test related to math, engineering, or physics. You gain Reliable 3 on all tests to figure out the function of a device or piece of equipment."},{"id":"engineer-cyberware-technician","name":"CYBERWARE TECHNICIAN","page":151,"cost":"10 Fortune","effect":"You can craft and upgrade cyberware. You may build cyberware using the rules for gear (see \"Advance Downtime Track\" on pg 36), and gain the normal decrease in costs. Installing cyberware built this way requires a TN 13 Science test. On a Failure, the recipient takes 3d6 physical damage and gains a Consequence. Any cyberware surgery you lead or assist with (unless you're the patient) gains Reliable 3."},{"id":"engineer-junkyard-maestro","name":"JUNKYARD MAESTRO","page":151,"cost":"20 Fortune","effect":"Requires 3 other Engineer. paradigm abilities. You may decrease the Fortune cost of any drone or vehicle you buy or build by 30% (round the final cost up). However, the first time each Action Mode you use a vehicle or drone purchased in this way, it takes 1 Irresistible Physical damage."}]},{"id":"watchdog","label":"Watchdog","items":[{"id":"watchdog-scan-the-scene","name":"SCAN THE SCENE","page":151,"cost":"10 Fortune","effect":"Gain a +1d6 on any Observation skill Test you make when looking for clues or concealed objects. Once per session, during a cinematic, you may use a Backup Action to make an Observation Test with a TN of 12. On a Success, increase your defenses by +1 for the remainder of the encounter."},{"id":"watchdog-paper-trail","name":"PAPER TRAIL","page":151,"cost":"10 Fortune","effect":"Gain Reliable 3 on any Observation or Humanities tests to find or interpret information in documents."},{"id":"watchdog-watch-closely","name":"WATCH CLOSELY","page":151,"cost":"10 Fortune","effect":"Gain +1d6 on any Observation skill Test you make when observing a person or situation, as well as any Physicality tests to avoid being noticed while you are watching someone."},{"id":"watchdog-rugged-mind","name":"RUGGED MIND","page":151,"cost":"10 Fortune","effect":"Whenever you spend Grit to reduce Animity damage, each point of Grit reduces the damage by two."},{"id":"watchdog-consulting-detective","name":"CONSULTING DETECTIVE","page":151,"cost":"10 Fortune","effect":"When you use the Side Gig Downtime Action (pg 37) you may gain a favor with one of your Relations or Factions involved in law enforcement."},{"id":"watchdog-good-listener","name":"GOOD LISTENER","page":152,"cost":"10 Fortune","effect":"Gain +1 to your dice pool when making any skill Test to gather information by talking to people (usually Influence or Deception). Once per Downtime, you may spend 2 Grit to take the Interact with Relation Downtime Action (see pg 37)without using up one of your Downtime Actions. BROWBEAT 10 Points. When you use the threaten action (pg 45), you may choose to double the effect (both the Regard penalty and the decreased Ask). DOGGED 10 Points. Once per session, after failing a skill Test you may take 5 Irresistible Animity or Health damage to gain a +5 on the roll. LINGO 10 Points. You’ve picked up a few phrases from many different languages, and you’re exceptionally good at reading facial expressions and body language. Whenever you attempt to understand someone who is using a language you do not know, you can understand the basic gist of what they are saying. This comprehension is surface-level; complex details and jargon will be impossible to grasp, but you get the general idea of what is being spoken about. This does not apply to understanding written text."},{"id":"watchdog-polyglot","name":"POLYGLOT","page":152,"cost":"20 Fortune","effect":"Requires Lingo and 2 other Watchdog. paradigm abilities. Whenever you encounter a language that you do not already know, you may spend 2 Fortune to become fluent in that language. This represents the fact that you’ve known that language all along, but it hasn’t come up yet – not a supernatural ability to instantly know a new language."},{"id":"watchdog-elementary-deductions","name":"ELEMENTARY DEDUCTIONS","page":152,"cost":"20 Fortune","effect":"Requires 3 other Watchdog. paradigm abilities. Once per session when making an Observation Test, you can change one rolled die to a 6."}]},{"id":"scoundrel","label":"Scoundrel","items":[{"id":"scoundrel-breaking-and-entering","name":"BREAKING AND ENTERING","page":152,"cost":"10 Fortune","effect":"Gain +1d6 to Observation or Physicality tests made to observe or bypass any physical form of security (locks, gates, fences, doors, razor wire, security sensors, etc). This does not apply to skill tests made against people or creatures."},{"id":"scoundrel-sweet-spot","name":"SWEET SPOT","page":152,"cost":"10 Fortune","effect":"Use a Backup Action and spend 1 Grit to reduce one of a target’s defenses against your actions by 3. Their defense returns to normal after your next turn ends. If you use a Main Action, the target’s defense is reduced against your allies’ actions as well as your own."},{"id":"scoundrel-ambush","name":"AMBUSH","page":153,"cost":"10 Fortune","effect":"You gain Augment 5 on all attacks against a target during the Surprise Round."},{"id":"scoundrel-streetwise","name":"STREETWISE","page":153,"cost":"10 Fortune","effect":"You gain Reliable 3 on Observation tests to determine if someone is involved in criminal activity. When you first encounter an NPC potentially willing to engage in illegal business with you, you may spend 1 Grit to increase their Regard with you by 5."},{"id":"scoundrel-light-fingers","name":"LIGHT FINGERS","page":153,"cost":"10 Fortune","effect":"Gain +1d6 on all Physicality tests for sleight of hand, pickpocketing, lock pick, or any other action to manipulate or steal something without being noticed. If a Failure or Dynamic Failure would cause you to lose Concealment, you lose only one point of Concealment."},{"id":"scoundrel-hamstring","name":"HAMSTRING","page":153,"cost":"20 Fortune","effect":"If you score a Dynamic Success when making an attack, your target can only move by taking a Main Action for a Minor Move and may not move above Speed zero. If you score a Critical Success on an attack, your target can only move 1m for every Main Action spent moving. This effect lasts either until the target spends 5 Grit or the end of the scene or encounter (whichever happens first)"},{"id":"scoundrel-stealth-mule","name":"STEALTH MULE","page":153,"cost":"10 Fortune","effect":"You can hide items no larger than a pistol on your person so well that any attempts to detect them suffers a penalty of –5 and do not hinder Concealment. You may conceal up to three items in this way."},{"id":"scoundrel-gambler","name":"GAMBLER","page":153,"cost":"10 Fortune","effect":"Gain +1d6 for any skill tests that are involved in gambling or games of chance. Whenever you engage in gambling Impulse or gamble as part of the Side Gig Downtime Action, gain 1d6-3 Fortune (this can be negative—take a Debt if you can't pay). Once per session, you may gamble by spending 1d6 Grit as an Interrupt Action. You may add or subtract that amount to any roll. If you are unable to pay the Grit cost, you instead spend 1 Grit and gain no effect."},{"id":"scoundrel-inconspicuous","name":"INCONSPICUOUS","page":153,"cost":"10 Fortune","effect":"Whenever your concealment (or the concealment of a group you are part of) would decrease, you may decrease the amount of concealment lost at a rate of 1 Grit per 2 concealment."},{"id":"scoundrel-irrepressible","name":"IRREPRESSIBLE","page":153,"cost":"10 Fortune","effect":"Once per session when you take Animity or Health damage, you may spend 1 Grit to reduce the damage by 2d6 to a minimum of 1 damage. You may not spend any other Grit to reduce the damage."},{"id":"scoundrel-slink-away","name":"SLINK AWAY","page":153,"cost":"10 Fortune","effect":"You can ignore up to two Consequences for the purposes of calculating Dulled on physicality tests to remain hidden."},{"id":"scoundrel-slinking-around","name":"SLINKING AROUND","page":153,"cost":"10 Fortune","effect":"When you use the Prepare for Trouble Downtime Action to increase a Concealment Track (see pg 37), you also gain 3 temporary Grit that can be spent on tests and abilities related to the infiltration."},{"id":"scoundrel-nothing-to-lose","name":"NOTHING TO LOSE","page":153,"cost":"20 Fortune","effect":"Requires 3 other Scoundrel. paradigm abilities. Spend 4 Grit to add +5 to any one test after learning the result."},{"id":"scoundrel-imperceptible","name":"IMPERCEPTIBLE","page":153,"cost":"30 Fortune","effect":"Requires Inconspicuous and 4 other. Scoundrel paradigm abilities. Whenever your Concealment (or the Concealment of a group you are part of) would decrease, you may decrease the amount of Concealment lost at a rate of 1 Grit per 5 Concealment. In tests related to stealth without a Concealment track, you may negate the effects of a Success (but not a Dynamic or Critical Success) by spending 1 Grit (instead of the normal 5)"}]},{"id":"breacher","label":"Breacher","items":[{"id":"breacher-aggressive-hack","name":"AGGRESSIVE HACK","page":154,"cost":"10 Fortune","effect":"Interrupt. You may spend 1 Grit to gain Augment 5 on all Breaching tests until the end of the scene. If you do, decrease your Security Rating by 2 until the end of the scene."},{"id":"breacher-breachwall","name":"BREACHWALL","page":154,"cost":"10 Fortune","effect":"Exploit. Interrupt. Spend 2 Grit to increase the Security Rating of a device within range by 5. You may do this after learning the result of a Test targeting the device to change the result of that Test."},{"id":"breacher-control","name":"CONTROL","page":154,"cost":"10 Fortune","effect":"Exploit. Target a drone, C-link, or other technology within your range. Roll Tech vs. target’s (or owner’s/ controller’s) Security Rating. On a Success, you give an order to the device that it will follow until the end of its next turn."},{"id":"breacher-intervene","name":"INTERVENE","page":154,"cost":"10 Fortune","effect":"Exploit. Interrupt. Spend 1 Grit. An ally may re-roll any number of dice on a failed test."},{"id":"breacher-gag","name":"GAG","page":155,"cost":"10 Fortune","effect":"Exploit. You interfere with the communications of a device without directly breaching it. Make a Tech test. Any devices of your choice with a Security Rating less than your result treat their range as T for all actions they take until the end of the next Round. On a Dynamic Success, this lasts for the next 10 Rounds. On a Critical Success this lasts as long as the device is within 1000m of you."},{"id":"breacher-force-shutdown","name":"FORCE SHUTDOWN","page":155,"cost":"10 Fortune","effect":"When you reduce the firewall of a device to zero, you may cause it to immediately shut down or be rendered inoperable as per the Disable Device Authorized Action (see pg 52)"},{"id":"breacher-tag","name":"TAG","page":155,"cost":"10 Fortune","effect":"You gain Augment 3 on all Tech tests to reduce the Concealment of another device."},{"id":"breacher-scan","name":"SCAN","page":155,"cost":"10 Fortune","effect":"Exploit. Choose a target you can see within range. The next ally to attack that target before the end of your next turn adds +2d6 to their skill Test."},{"id":"breacher-ghost-in-the-system","name":"GHOST IN THE SYSTEM","page":155,"cost":"10 Fortune","effect":"When you spend Grit to prevent the loss of Concealment while breaching, each point of Grit spent prevents 3 points of Concealment loss."},{"id":"breacher-coordinate","name":"COORDINATE","page":155,"cost":"10 Fortune","effect":"Exploit. Target ally may spend 1 Grit to use an additional Main Action after everyone else has acted this Round."},{"id":"breacher-swift-access","name":"SWIFT ACCESS","page":155,"cost":"10 Fortune","effect":"You may spend 2 Grit to use an authorized access action as a Backup Action."},{"id":"breacher-overwatch","name":"OVERWATCH","page":155,"cost":"10 Fortune","effect":"Exploit. Interrupt. Spend 1 Grit. Target ally may use your Vigilance score instead of theirs until the end of your next turn. You may spend Grit to increase your Vigilance for this Exploit by 1 for each Grit spent."},{"id":"breacher-subversive-breach","name":"SUBVERSIVE BREACH","page":155,"cost":"10 Fortune","effect":"You gain +2d6 on all Deception tests made to falsify data."},{"id":"breacher-acquire-target","name":"ACQUIRE TARGET","page":155,"cost":"20 Fortune","effect":"Exploit. Requires Intervene. Choose a number of targets within line of sight equal to one plus your ranks in Tech. Until the end of the scene, whenever an Ally spends a point of Grit to re- roll a die on an attack targeting those targets, they may re-roll any number of dice."},{"id":"breacher-spoof-message","name":"SPOOF MESSAGE","page":155,"cost":"20 Fortune","effect":"Exploit. You send a message that appears to be from a different source. If your Tech test beats their Security Rating, you or an ally may make a Deception test with a +5 bonus to convince them the message is real."},{"id":"breacher-heads-up-display","name":"HEADS UP DISPLAY","page":155,"cost":"10 Fortune","effect":"Exploit. Increase Guard for all allies within 100m by 3 for 2 Rounds."},{"id":"breacher-ocular-assault","name":"OCULAR ASSAULT","page":155,"cost":"10 Fortune","effect":"Exploit. Requires Tag. Target a number of halos or cyber eyes equal to one plus your ranks in Tech. If your Tech Test is above the Security Rating of your targets, their users have a Consequence until the end of your next turn."},{"id":"breacher-obscure-target","name":"OBSCURE TARGET","page":155,"cost":"10 Fortune","effect":"Exploit. Interrupt. Requires Tag. Target one sensor or security system with the potential to detect one of your allies. If you succeed on the Exploit, you may spend 3 Grit to negate any Success (but not Dynamic or Critical Success) that would lead to you or your allies losing Concealment or otherwise being detected. Reduce the cost of this Exploit to one Grit if the targeted device is the only method for spotting your ally."}]},{"id":"jumper","label":"Jumper","items":[{"id":"jumper-remote-monitor","name":"REMOTE MONITOR","page":156,"cost":"10 Fortune","effect":"You’re accustomed to monitoring sensor feeds for signs of trouble. Gain Reliable 3 on all Observation tests using remote sensors from a drone or vehicle."},{"id":"jumper-quick-reflexes","name":"QUICK REFLEXES","page":156,"cost":"10 Fortune","effect":"Whenever you are actively controlling a drone or vehicle you gain +2 Initiative, and reduce the Grit cost to act in a Surprise Round by one."},{"id":"jumper-defensive-posture","name":"DEFENSIVE POSTURE","page":156,"cost":"10 Fortune","effect":"Drones and vehicles you control gain +2 Guard, and the Pursuit Track to catch you is increased by 5."},{"id":"jumper-vehicle-hookup","name":"VEHICLE HOOKUP","page":156,"cost":"10 Fortune","effect":"Pick a Swag: Vehicle (see \"Swag\" on pg 123) Relation you have. As long as you have positive Regard with them, you may decrease your lease costs by their Power instead of the normal discount due to caste (see \"Buying and Leasing Vehicles\" on pg 112). If you lose or destroy the vehicle, decrease their Base Regard to you by 5."},{"id":"jumper-signal-splicer","name":"SIGNAL SPLICER","page":156,"cost":"10 Fortune","effect":"You're an expert of finding a way to get a connection to one of your drones or vehicles, maintaining a wide range of redundant paths. You are never affected by environmental conditions that block signals unless they completely block all connections (GM discretion). Whenever a drone or vehicle that you’re an Authorized User of would have its range reduced so that you can’t access it (for example, through the Gag Exploit or by someone taking the Change Range Authorized Action), you may spend 1 Grit to negate that effect."},{"id":"jumper-combat-jumper","name":"COMBAT JUMPER","page":156,"cost":"10 Fortune","effect":"You gain Augment 2 on all attacks made with a drone or vehicle."},{"id":"jumper-racer","name":"RACER","page":156,"cost":"10 Fortune","effect":"You gain Augment 2 on all Piloting tests made in chases (see pg 55) or as part of a race."},{"id":"jumper-machine-empathy","name":"MACHINE EMPATHY","page":157,"cost":"10 Fortune","effect":"You have a personal understanding of how your drones and vehicles work. You gain +1d6 and Reliable 3 on any Tech tests on a vehicle you own or have spent a Downtime Action building or repairing."},{"id":"jumper-made-for-speed","name":"MADE FOR SPEED","page":157,"cost":"10 Fortune","effect":"When you take the Major Move (pg 33) action to exceed the maximum Speed of a vehicle you own or have spent extensive time modifying (at least one Downtime Action repairing), the increase in top Speed lasts for as long as you continue at that Speed, though you continue to take damage each Round. You gain Augment 1 on all chase tests while above your normal top Speed."},{"id":"jumper-quick-jockeying","name":"QUICK JOCKEYING","page":157,"cost":"10 Fortune","effect":"When you take the Major Move (pg 33) action in a vehicle, you may also take the Focus action (see pg 34) as a Free Action."},{"id":"jumper-breach-spikes","name":"BREACH SPIKES","page":157,"cost":"20 Fortune","effect":"Requires 3 other Jumper. paradigm abilities. Increase the Security Rating of you and all your vehicles by 2. Whenever a breacher fails an Exploit or Breaching test targeting you or a drone or vehicle you control, they lose 3 concealment and gain an instance of Dulled on Tech tests targeting you for the remainder of the scene."},{"id":"jumper-impossible-stunt","name":"IMPOSSIBLE STUNT","page":157,"cost":"30 Fortune","effect":"Requires 6 other Jumper. paradigm abilities. You can pull off a remarkable stunt. After making a Piloting test with a vehicle and learning its result, you may spend 5 Grit to gain a +5 on the roll. If you do so, you immediately gain another Main Action with the piloted vehicle, and it gains +5 Guard until the end of your next turn."}]},{"id":"cyberware","label":"Cyberware","items":[{"id":"cyberware-basic-datajack","name":"BASIC DATAJACK","page":157,"cost":"10 Fortune","effect":"A cybertech implant wired directly into your brain. Normally implanted on the side of the head, back of the neck, or more rarely, on the hand or arm. They are mostly used by corporate coders, but breachers need them to connect to their cyberkits. You gain Reliable 2 with any connected halo or cyberkit, or to interact with any device you are directly connected to. Additionally, the biometric authentication you use to connect to any halos or cyberkits cannot be hacked (see \"Access security\" on pg 53)"},{"id":"cyberware-full-body-datajack","name":"FULL BODY DATAJACK","page":157,"cost":"20 Fortune","effect":"Requires Basic Datajack. You’ve given up pieces of yourself to upgrade that datajack with backup relays, enhancers, and boosters littered through your body. It’s efficient and feels a bit more natural all the time. Upgrade the bonus from basic datajack to Reliable 3 and gain +2 Security Rating for any of your devices connected to your datajack."},{"id":"cyberware-cyberkit","name":"CYBERKIT","page":157,"cost":"10 Fortune","effect":"Requires Basic Datajack. A cyberkit is the tool that makes a breacher a breacher. Each one is unique, cobbled together from scavenged, stolen, or purchased parts, and interacts with a datajack to manipulate cybertech. You gain a cyberkit with Security Rating 13, Firewall 10, Breach Power 5, Slicing +0, and 2 Enhancement Slots."},{"id":"cyberware-cyberkit-expansion","name":"CYBERKIT EXPANSION","page":158,"cost":"10 Fortune","effect":"Requires Cyberkit. Your cyberkit gains +2 enhancement slots. ELITE CYBERKIT EXPANSION 20 Fortune. Requires Cyberkit Expansion Your cyberkit gains +2 enhancement slots."},{"id":"cyberware-cyberkit-enhancement","name":"CYBERKIT ENHANCEMENT","page":158,"cost":"10 Fortune","effect":"Requires Cyberkit. You may take this paradigm multiple times. Each option may only be taken once, however. Choose one enhancement, which takes up one enhancement slot on your cyberkit: ※ Improved Security: Security Rating +2 ※ Improved Firewall: Firewall +5 ※ Improved Breach Power: Breach Power +3 ※ Improved Slicing: Slicing +1."},{"id":"cyberware-elite-cyberkit-enhancement","name":"ELITE CYBERKIT ENHANCEMENT","page":158,"cost":"20 Fortune","effect":"Requires Cyberkit Enhancement. You may take this paradigm multiple times. Each enhancement may only be taken once. Choose one enhancement, which takes up one enhancement slot on your cyberkit: ※ Elite Security: Security Rating +2 (requires the Improved Security enhancement) ※ Elite Firewall: Firewall +5 (requires the Improved Firewall enhancement) ※ Elite Breach Power: Breach Power +3 (requires the Improved Breach Power enhancement) ※ Elite Slicing: Slicing +1 (requires the Improved Slicing enhancement)"},{"id":"cyberware-wired-synapses","name":"WIRED SYNAPSES","page":158,"cost":"10 Fortune","effect":"2 Enhancement Slots. You may spend 1 Grit to take an additional Backup Action at the end of your turn. You may not take a Backup Action if you have already taken that Backup Action on your turn."},{"id":"cyberware-wired-synapses-enhancement","name":"WIRED SYNAPSES ENHANCEMENT","page":158,"cost":"10 Fortune","effect":"Requires Wired Synapses. You may take this paradigm multiple times. Each enhancement may only be taken once. Choose one enhancement, which takes up one enhancement slot on your wired synapses: ※ Combat Synapses: Spend 1 Grit to be Inspired on a Ranged or Melee Attack action. ※ Athlete Synapses: Spend 1 Grit to be Inspired on a Physicality skill Test. ※ Jumper Synapses: Spend 1 Grit to be Inspired on a Piloting skill Test. ※ Muscle Accelerator: +1 Guard and +2 Initiative. ※ Sensory Booster: +1 Vigilance and +2 Initiative."},{"id":"cyberware-wired-synapses-expansion","name":"WIRED SYNAPSES EXPANSION","page":158,"cost":"10 Fortune","effect":"Requires Wired Synapses. Your wired synapses gains +2 enhancement slots."},{"id":"cyberware-wired-synapses-elite-enhancement","name":"WIRED SYNAPSES ELITE ENHANCEMENT","page":158,"cost":"20 Fortune","effect":"Requires Wired Synapses. This enhancement for Wired Synapses takes up 2 enhancement slots on your wired synapses. You may spend 3 Grit to take an additional Main Action."},{"id":"cyberware-cybernetic-eyes","name":"CYBERNETIC EYES","page":158,"cost":"10 Fortune","effect":"2 Enhancement Slots. Gain +1d6 to Observation skill tests where vision is relevant. You can take photos and videos using your eyes, and store a virtually unlimited amount of media files."},{"id":"cyberware-cybernetic-eyes-expansion","name":"CYBERNETIC EYES EXPANSION","page":158,"cost":"10 Fortune","effect":"Requires Cybernetic Eyes. Your cybernetic eyes gain +2 enhancement slots."},{"id":"cyberware-cybernetic-eyes-enhancement","name":"CYBERNETIC EYES ENHANCEMENT","page":158,"cost":"10 Fortune","effect":"Requires Cybernetic Eyes. You may take this paradigm multiple times. Each enhancement may only be taken once. Choose one enhancement, which takes up one enhancement slot on your cybernetic eyes: ※ Enhanced Spectrum: Low-light and thermographic vision. You never suffer penalties to visual Observation skill tests due to environmental or lighting conditions. ※ Eye Flare: Once per session your eyes emit a bright flash of light. Anyone (excepting yourself) within 10m that can see you suffers one instance of Dulled until the end of your next turn. ※ Flare Compensation: Your eyes automatically compensate for intense or sudden light. You are immune to any attack that uses bright or flashing lights to achieve its effect. ※ Microscopic Vision: Your eyes have a microscopic vision mode, which can only be used up close (within 1 meter). Gain +2d6 to Observation skill tests when searching for details up close, and +1d6 to Sciences skill tests when attempting to analyze something. ※ Mini-Dart Launcher: Each eye contains a one- shot dart launcher with a maximum range of 10m. You may load any drug or toxin into the darts. Reloading takes 5 minutes. ※ Target Assist: If you take an Aim action before making a Ranged Attack, you also gain +1 dice pool on the attack Test. ※ Visual Threat Detection System: +1 to Guard and Vigilance against any threat you can see."},{"id":"cyberware-cybernetic-ears","name":"CYBERNETIC EARS","page":159,"cost":"10 Fortune","effect":"2 Enhancement Slots. Gain +1d6 to Observation skill tests where hearing is relevant. You can record audio using your ears, and store a virtually unlimited amount of media files."},{"id":"cyberware-cybernetic-ears-expansion","name":"CYBERNETIC EARS EXPANSION","page":159,"cost":"10 Fortune","effect":"Requires Cybernetic Ears. Your cybernetic ears gain +2 enhancement slots."},{"id":"cyberware-cybernetic-ears-enhancement","name":"CYBERNETIC EARS ENHANCEMENT","page":159,"cost":"10 Fortune","effect":"Requires Cybernetic Ears. You may take this paradigm multiple times. Each enhancement may only be taken once. Choose one enhancement, which takes up one enhancement slot on your cybernetic ears: ※ Auditory Threat Detection System: +1 to Guard and Vigilance against any threat that you can hear. ※ Directional Analyzer: With a successful auditory Observation skill Test, you can precisely tell the exact position of the source of a sound that you heard. ※ Enhanced Balance: Once per encounter, when you would be knocked down, fall, or otherwise lose your balance, you remain on your feet and steady instead. ※ Full-Spectrum Hearing: You are able to perceive subsonic and ultrasonic sound. You automatically detect ultrasound sensors (which include motion sensors), and you may make auditory Observation tests to detect the presence of electronics. ※ Noise Filter: You are able to selectively filter out background noise and other sounds that you would prefer to ignore. Once per session, you may ignore a failed auditory Observation Test, which counts as a Dynamic Success instead. ※ Protective Dampening: Your ears protect you from harmful sound pressure. You are immune to any effect that results from loud or sudden sounds."},{"id":"cyberware-cybernetic-arm","name":"CYBERNETIC ARM","page":159,"cost":"10 Fortune","effect":"2 Enhancement Slots. Not just a prosthetic replacement, your cyberarm is a technological marvel, and an improvement over the biological limb it replaces. You gain Reliable 2 on all tests primarily using your arms, and Augment 1 on all Melee Attacks and Brawn based tests using your arms. If you have two cybernetic arms (taking this ability twice), you instead gain Augment 2 and Reliable 3 on all such tests."},{"id":"cyberware-cybernetic-arm-expansion","name":"CYBERNETIC ARM EXPANSION","page":160,"cost":"10 Fortune","effect":"Requires Cybernetic Arm. Your cyberarm gains +2 enhancement slots."},{"id":"cyberware-cybernetic-arm-enhancement","name":"CYBERNETIC ARM ENHANCEMENT","page":160,"cost":"10 Fortune","effect":"Requires Cybernetic Arm. You may take this paradigm multiple times. Choose one enhancement, which takes up one enhancement slot on your cybernetic arm. Each enhancement may only be taken once. ※ Enhanced Stabilizers: +1d6 on Agility based tests using your arms when you take the Focus/ Aim actions (see pg 34). ※ Enhanced Brawn: Increase the Augment from your arms by 2. ※ Cyberweapon: Choose a one-handed weapon that is concealed within your cyberarm. Detecting the weapon requires a TN 14 Observation test from someone looking for concealed weapons. You must spend a Backup Action to deploy or conceal your cyberweapon. You must pay the Fortune cost for the weapon in addition to the Fortune for this enhancement choice. ※ Grapple Launcher: You may launch a grapple line at a target within 50 m as a Main Action and retract it with enough force to pull you up at your normal move Speed (taking actions to move as normal) ※ Rugged Design: +5 Health ※ Smuggling Pod: You can conceal an object no larger than a pistol inside a sealed compartment. Detecting the object requires a TN 15 Observation test. Inserting or removing the concealed object requires 1 Main Action."},{"id":"cyberware-cybernetic-legs","name":"CYBERNETIC LEGS","page":160,"cost":"20 Fortune","effect":"2 Enhancement Slots. Enhanced cyberlegs are always sold as a pair. You gain Augment 2 and Reliable 3 on all actions that primarily rely on your legs (including physicality tests in chases)"},{"id":"cyberware-cybernetic-legs-expansion","name":"CYBERNETIC LEGS EXPANSION","page":160,"cost":"10 Fortune","effect":"Requires Cybernetic Legs. Your cyberlegs gain +2 enhancement slots."},{"id":"cyberware-cybernetic-legs-enhancement","name":"CYBERNETIC LEGS ENHANCEMENT","page":160,"cost":"10 Fortune","effect":"You may take this paradigm multiple times. Choose one enhancement, which takes up one enhancement slot on your cybernetic leg. Each enhancement may only be taken once. ※ Enhanced Agility: +1d6 on Agility linked Physicality tests related to movement, such as stealth or balance. ※ Speed: You gain a maximum Speed of 2. ※ Enhanced Speed (Requires Speed): You gain a maximum Speed of 3 and Acceleration 2. ※ Extendable Legs: You are able to extend your legs to increase your height by up to 1 meter, or reduce their length to make yourself shorter. In addition to never needing a stepladder again, you also gain a +2 bonus on any skill tests to impersonate someone by matching their height. ※ Cyberweapon: Choose a one-handed weapon that is concealed within your cyberleg. Detecting the weapon requires a TN 14 Observation test from someone looking for concealed weapons. You must spend a Backup Action to deploy or conceal your cyberweapon. You must pay the Fortune cost for the weapon in addition to the Fortune for this enhancement choice.\b ※ Mag-feet: You can magnetize your feet, allowing you to cling to metal surfaces and objects. ※ Jump Jets: +2d6 on Physicality tests to jump. ※ Rugged Design: Gain +5 Health. ※ Smuggling Pod: You can conceal an object no larger than a pistol inside a sealed compartment. Detecting the object requires a TN 15 Observation test. Inserting or removing the concealed object requires 1 Main Action."},{"id":"cyberware-cybertech-lungs","name":"CYBERTECH LUNGS","page":160,"cost":"10 Fortune","effect":"Gain +3 Health. You can hold your breath for up to one hour. You are immune to inhaled toxins."},{"id":"cyberware-cybertech-heart","name":"CYBERTECH HEART","page":160,"cost":"10 Fortune","effect":"Gain +2 Health. Gain Reliable 3 on all Physicality tests related to endurance, and you never take Health damage for running above your max Speed (see \"Major Move\" on pg 33)"},{"id":"cyberware-cybertech-liver","name":"CYBERTECH LIVER","page":161,"cost":"10 Fortune","effect":"Gain +3 Health. You are immune to all injected toxins. You may spend 3 Grit to end the effect of a drug you are under the effect of."},{"id":"cyberware-cybertech-stomach","name":"CYBERTECH STOMACH","page":161,"cost":"10 Fortune","effect":"Gain +3 Health. You are immune to all ingested toxins. You process food more efficiently, requiring only half as much food. You are able to go without food for 3 days before suffering any ill effects."},{"id":"cyberware-cyberskin","name":"CYBERSKIN","page":161,"cost":"10 Fortune","effect":"2 Enhancement Slots. Synthetic skin covers and protects your entire body, including (if you choose) your cybernetic limbs. Gain +2 Armor."},{"id":"cyberware-cyberskin-enhancements","name":"CYBERSKIN ENHANCEMENTS","page":161,"cost":"10 Fortune","effect":"Requires Cyberskin. You may take this paradigm multiple times. Choose one enhancement, which takes up one enhancement slot on your cyberskin. Each enhancement may only be taken once. ※ Active Camouflage: You must have the Appearance Control enhancement in order to take Active Camouflage. You have a low-resolution micro camera array built into your cyberskin that allows it to adapt to your background and blend into your surroundings. When you are naked or only wearing clothes with similar abilities (such as the Stealth Suit (pg 106) or Synthleather Clothing (pg 110) with the Pattern Shift enhancement), gain +2 to your dice pool on any skill tests to hide or sneak while you are nearly naked (use the higher of this bonus or any bonus from worn gear with similar abilities). ※ Armorskin: +3 Health and +1 Armor. ※ Appearance Control: You can change the appearance of your skin to alter your physical appearance, including skin tone, tattoos or other markings, facial shape, and hair. You gain +2 to your dice pool on any Deception skill tests when you are attempting to disguise yourself or impersonate someone else. This enhancement is incompatible with Armorskin. ※ Enhanced Sensory Interface: Your cyberskin has enhanced sensory ability. In addition to improved tactile sensory ability, your skin is covered with chemoreceptors that allow you to determine the chemical composition of anything you touch. Gain +2d6 on all Observation tests involving touch or Observation or Science Tests to determine the chemical composition of a material (including trace compounds such as drugs, poisons, or gunpowder residue). This enhancement is incompatible with Armorskin."},{"id":"cyberware-cybertail","name":"CYBERTAIL","page":161,"cost":"10 Fortune","effect":"2 Enhancement Slots. A cybernetic prehensile tail. It can grab and hold things, but not perform actions with them. Gain +1 to Guard and +1d6 to any Physicality Test that involve careful balance or climbing."},{"id":"cyberware-cybertail-enhancements","name":"CYBERTAIL ENHANCEMENTS","page":161,"cost":"10 Fortune","effect":"Requires Cybertail. You may take this paradigm multiple times. Choose one enhancement, which takes up one enhancement slot on your cybertail. Each enhancement may only be taken once. ※ Handy Tail: At the end of your tail is a small hand. Your tail is capable of fine manipulation, not just grabbing and holding things. Once per turn you may take the Interact (pg 34) action as Free Action instead of a Backup Action. This enhancement is incompatible with Stinger or Syringe Stinger. ※ Retractable Tail: You may extend or reduce the length of your cybertail at will, or retract it completely in order to conceal it. You may use your tail (including any enhancements) to target any object within 10m. ※ Tail Blade: At the end of your tail is a blade, which can be retracted into a sheath in order to conceal its presence. Damage 1d6+Brawn, AP 3. This enhancement is incompatible with Handy Tail or Syringe Stinger. ※ Syringe Stinger: At the end of your tail is a retractable stinger, designed to pierce the skin and inject a drug or toxin. By default the syringe stinger is loaded with a powerful tranquilizer. On a successful Melee Attack with the Syringe Stinger, the target must make a Physicality test against a TN of 13. On a Failure, they take 5d6 Metabolic damage. On a Success they take 1d6 Metabolic damage and are immune to the effect of Syringe Stinger for the remainder of the scene. The damage from this enhancement is always nonlethal. This enhancement is incompatible with Handy Tail or Tail Blade. ※ Hold-out Tail: Your tail has a concealed single shot pistol built into it. Make a ranged attack with a range of 50m. On a Success, do 4d6 damage. This can be reloaded with 5 minutes of effort. This is incompatible with any other tail enhancement."},{"id":"cyberware-sustaining-cybertech","name":"SUSTAINING CYBERTECH","page":162,"cost":"10 Fortune","effect":"A combination of synthetic endocrine glands, neural implants, and enhanced energy stores enable you to work for sustained periods of time without food or sleep. You may skip one night of sleep by taking 1 Irresistible Animity damage, or one day of food by taking 1 Irresistible Health damage. If you use this during Downtime, you may take 3 Irresistible Animity damage to gain one additional Downtime Action. This may not be combined with similar effects, such as from Flow (pg 102), to gain more than 1 bonus Downtime Action."},{"id":"cyberware-mnemonic-enhancer","name":"MNEMONIC ENHANCER","page":162,"cost":"20 Fortune","effect":"Requires Datajack. You have some saved data or memories stored in cybertech so that you can access it perfectly; you can choose perfect recall of one particular memory at a time. Gain Reliable 3 on Tech, Humanities, and Science tests."},{"id":"cyberware-reaction-enhancers","name":"REACTION ENHANCERS","page":162,"cost":"20 Fortune","effect":"Interrupt. Requires Sustaining. Cybertech Hopped up on synthetic adrenaline, you move with a skittery speed. You can spend 1 Grit to add +2 to Guard and Vigilance until the start of your next turn."}]},{"id":"college-of-mana","label":"College of Mana","items":[{"id":"college-of-mana-aetherlight-ditty","name":"AETHERLIGHT DITTY","page":163,"cost":"10 Fortune","effect":"Ditty. Sustainable. You create Aetherlight, an invisible light that causes any magical effects and spirits within 10m range to glow, becoming immediately visible, even to characters not using Shinesight (see \"Shine Perception\" on pg 61). You can identify the nature of the magic with a TN 10 Magic Arts Test, with higher results giving more detail."},{"id":"college-of-mana-ditty-of-aegis","name":"DITTY OF AEGIS","page":163,"cost":"10 Fortune","effect":"Ditty. Sustainable. You make a touched target more resistant to magic, raising their Aegis by 4 until the end of the next Round."},{"id":"college-of-mana-accelerated-harmonies","name":"ACCELERATED HARMONIES","page":163,"cost":"10 Fortune","effect":"You may spend 3 Grit to harmonize as a Backup Action. Magic."},{"id":"college-of-mana-anchored-ditties","name":"ANCHORED DITTIES","page":163,"cost":"10 Fortune","effect":"You learn to anchor long duration effects in one place. You may roll Magic Arts vs TN 10 to spend a Downtime Action to cast a ditty with the sustainable keyword. As long as the target moves no further than 10m, the spell lasts until the end of the next Downtime. Dynamic and Critical Successes cause the spell to last for additional Downtimes. Such effects are always in high demand, and you gain +1 Fortune when you successfully use Magic Arts as part of the Side Gig Downtime Action."},{"id":"college-of-mana-dispel","name":"DISPEL","page":163,"cost":"10 Fortune","effect":"Spell. Cost: 1 Mana Bar. Pick an ongoing spell within 100m. You make an opposed Magic Arts test against the originator of the spell. On a Success, you end the spell. The opposing caster gets a +2 for each bar or point of dissonance involved in casting the spell. Amp: For each Mana Bar you harmonize on this spell (including the base cost of the spell), you get a +3 on your roll."},{"id":"college-of-mana-echoing-spell","name":"ECHOING SPELL","page":164,"cost":"10 Fortune","effect":"As a Main Action, you may spend 1 Grit to recast a spell you cast the previous Round, ignoring any requirements for harmonized bars. Gain an additional instance of Dulled on any rolls to cast the spell."},{"id":"college-of-mana-enduring-spell","name":"ENDURING SPELL","page":164,"cost":"10 Fortune","effect":"Spell. Cost: 1 Mana Bar. Sustainable. This spell may be sustained as a Free Action. While this spell is sustained, the caster may sustain one other spell as a Free Action. Amp: For each Mana Bar you spend on this Amp, you may sustain an additional spell as a Free Action."},{"id":"college-of-mana-covert-spell","name":"COVERT SPELL","page":164,"cost":"10 Fortune","effect":"By default, harmonizing is obvious, as the channeled mana leaves after effects and residual energy which is clearly visible (see \"Harmonize\" on pg 62). You have learned the art of carefully shaping that magic in order to avoid notice. When you harmonize a Mana Bar, you leave no physical effect, instead requiring a Magic Perception test against a TN equal to 14+your ranks in Magic Arts. You may also hide harmonizing for other bars. All of your spells gain the following Amp: Amp: 1 Mana Bar. You hide the harmonizing while casting this spell. After harmonizing a Mana Bar, you may spend it on this Amp. All other bars harmonized for this spell leave no physical residue, and require a magic perception test against a TN equal to 14+your ranks in Magic Arts to notice."},{"id":"college-of-mana-storm-warden","name":"STORM WARDEN","page":164,"cost":"10 Fortune","effect":"You've trained as a storm warden to protect settlements from tempests and mana storms (see pg 268). You may affect any tempest where you can see the affected area, as well as any tempest within 5km, regardless of if you can see it. Whenever a tempest enters that range, you gain the opportunity to immediately become aware of it with a TN 13 Magic Arts test, gaining a bonus on this test equal to the Power of the tempest. You may start reducing the power of a tempest even before finishing harmonizing your Bars—as long as you have harmonized one Bar you may attempt to quell the tempest as a Backup Action while continuing to harmonize additional Bars. Storm wardens are always in high demand to protect communities. If you use this ability as part of the Side Gig Downtime Action, the GM does not gain Grit."},{"id":"college-of-mana-steal-spell","name":"STEAL SPELL","page":164,"cost":"20 Fortune","effect":"Spell. Cost: 2 Mana Bars. Requires. Dispel and 2 other College of Mana abilities. Pick an ongoing spell within 100m. You make an opposed Magic Arts test against the originator of the spell. On a Success, you gain control of the spell. The opposing caster gets a +2 for each Bar or point of Dissonance involved in casting the spell. Amp: For each Mana Bar you harmonize on this spell, you get a +3 on your test."},{"id":"college-of-mana-artificing","name":"ARTIFICING","page":164,"cost":"20 Fortune","effect":"Spell. Cost: 2 Mana Bars. Requires. Anchored Ditties and 2 other College of Mana abilities. You can sustain spells cast by you or others to create magical items powered by pure mana. As a Downtime Action, you may create a magical item capturing the effect of any spell you can cast— optionally, you may capture the spell of another character who takes a Downtime Action with you. Pay 1 Fortune base, +1 additional Fortune for each bar or dissonance in the spell. You create a single use magical item that can be activated with a TN 12 Magic Arts Test. Amp: 1 Mana Bar. You may make a spell with the sustainable keyword activate continuously. Once activated, this effect lasts until the beginning of the next Downtime."},{"id":"college-of-mana-mana-mastery","name":"MANA MASTERY","page":164,"cost":"20 Fortune","effect":"5 other College of Mana abilities. Free Action. Once per turn, you may spend 1 Grit to add 1 Mana Bar to an Amp without harmonizing for that bar."}]},{"id":"college-of-force","label":"College of Force","items":[{"id":"college-of-force-absorbing-ditty","name":"ABSORBING DITTY","page":165,"cost":"10 Fortune","effect":"Ditty. Sustainable. Gain +3 Physical Armor until the end of the next Round. Amp: For each Force Bar used (or added), increase Physical Armor by +3."},{"id":"college-of-force-delicate-touch","name":"DELICATE TOUCH","page":165,"cost":"10 Fortune","effect":"Ditty. The caster can manipulate an object of less than 5 kg (10lbs) within 50m as if they were touching it. If the object is attended, make a Magic Arts Test vs the attending character's Aegis to grab it."},{"id":"college-of-force-force-field","name":"FORCE FIELD","page":165,"cost":"10 Fortune","effect":"Spell. Cost: 1 Force Bar. Sustainable. Requires Absorbing Ditty. The caster diminishes all physical impacts within an area. All individuals within 10m of you gain +4 Armor against Physical damage. Amp: The caster may spend 1 Force Bar to only affect targets they choose within range Amp: For each Force Bar spent on this Amp, increase Physical Armor by +3."},{"id":"college-of-force-alarm","name":"ALARM","page":165,"cost":"10 Fortune","effect":"Spell. Sustainable. You’ve created a web of invisible strings within 1000m of you to absorb minute amounts of kinetic energy. These spells are not enough to stop anything before being overwhelmed, but you are aware whenever they have been crossed. If you possess the Anchored Ditties paradigm ability, you may cast this as a Downtime Action; if you do, all enemies reduce their starting Concealment by 6 when sneaking in the Community and gain an instance of Dulled on all Physicality Tests to sneak while in the Community."},{"id":"college-of-force-five-finger-force-flick","name":"FIVE FINGER FORCE FLICK","page":165,"cost":"10 Fortune","effect":"Spell. Cost: 1 Force Bar. You impact a target within 50m with damaging force. Roll Magic Arts vs Aegis, on a Success move the target 20m in a direction of your choice, dealing 4d6 damage to them. Amp: For each additional Force Bar used casting this spell, do an additional 3d6 physical damage to the target."},{"id":"college-of-force-silence","name":"SILENCE","page":165,"cost":"10 Fortune","effect":"Spell. Cost: 1 Force Bar. Sustainable. You or a touched target makes no noise. Gain +2 on all Physicality Tests to avoid being detected in situations where hearing matters until the end of the next Round."},{"id":"college-of-force-kinetic-whip","name":"KINETIC WHIP","page":166,"cost":"10 Fortune","effect":"Spell. Cost: 1 Force Bar. Sustainable. You use your power to levitate a long coil of flexible material around you—traditionally this spell is cast with water, though dirt, debris, or anything else malleable works as well. You can manipulate it to intercept attacks, gaining +2 Guard. When you cast or sustain this spell, you may make a Magic Arts test against the Guard of a target in T range, doing 2d6 Physical damage on a Success. Amp: For each additional Force Bar used on this Amp, increase damage by 1d6 Amp: For each additional Force Bar used on this Amp, increase Guard by an additional +2."},{"id":"college-of-force-levitate","name":"LEVITATE","page":166,"cost":"20 Fortune","effect":"Spell. Cost: 1 Force Bar. Sustainable. Requires 3 other College of Force abilities. You or touched target weighing less than 200kg becomes weightless until the end of the next Round. Amp: 1 Force Bar. When casting or sustaining this spell, you may move 10m for each Force Bar spent on this Amp Amp: You may select a group of people or objects within 10m of each other to affect with this spell, with a total weight not to exceed 500kg per bar used on this Amp."},{"id":"college-of-force-force-mastery","name":"FORCE MASTERY","page":166,"cost":"20 Fortune","effect":"Requires 5 other College of. Force abilities. Free Action. Once per turn, you may spend 1 Grit to add 1 Force Bar to a Amp without harmonizing for that bar."}]},{"id":"college-of-light","label":"College of Light","items":[{"id":"college-of-light-ditty-of-light","name":"DITTY OF LIGHT","page":166,"cost":"10 Fortune","effect":"Ditty. Sustainable. The caster can create a bright light of a color of their choice comparable to a bright electric light. Increase your Guard by 2 until your next turn."},{"id":"college-of-light-darkness","name":"DARKNESS","page":166,"cost":"10 Fortune","effect":"Spell. Cost: 1 Light Bar. Sustainable. The caster shrouds a radius of up to 50m around them, providing a -4 penalty to all applicable Observation tests and rolls targeting Guard within the area until the end of your next turn. This effect is obvious under most conditions, and your Concealment is capped at 10 when using or sustaining this spell."},{"id":"college-of-light-trick-of-the-light","name":"TRICK OF THE LIGHT","page":166,"cost":"10 Fortune","effect":"Ditty. You may make a Divert Action (see pg 48) using Magic Arts. If you fail, decrease your Concealment by 5 (instead of being automatically discovered. Amp: For each Light Bar added, on a Success you increase Concealment by 3, and on a Failure, reduce the decrease in your Concealment by 2."},{"id":"college-of-light-light-show","name":"LIGHT SHOW","page":166,"cost":"10 Fortune","effect":"Spell. Requires Anchored Ditties. You create pleasing lights around your Community that illuminate the streets and make public spaces safer. You may spend a Downtime Action to make a TN 10 Arts test; on a Success, everyone in your Community regains 2 Animity."},{"id":"college-of-light-no-dark-alleys","name":"NO DARK ALLEYS","page":166,"cost":"10 Fortune","effect":"Spell. Requires Light Show. It is hard to do evil in the shadows if there are fewer shadows. When you use the Downtime Action from the Light Show paradigm ability, everyone in your Community gains Adamant 2 and all Observation tests in your Community gain Augment 1. This lasts until your next Downtime."},{"id":"college-of-light-invisibility","name":"INVISIBILITY","page":166,"cost":"10 Fortune","effect":"Spell. Cost: 2 Light Bars. Sustainable. You or a target within 50m becomes invisible until the end of the next Round. This grants a +5 on all physicality tests to be stealthy in situations where vision is important."},{"id":"college-of-light-laser","name":"LASER","page":167,"cost":"10 Fortune","effect":"Spell. Cost: 1 Light Bar. The caster pinpoints a target within 50m with a ray of light. Roll Magic Arts vs Aegis, on a Success, deal 4d6 damage, and all attacks against the target until the end of your next turn get +2d6. Amp: For each additional Light Bar used casting this spell, do +2d6 damage and add an additional +1d6 on attacks against the target."},{"id":"college-of-light-minor-illusion","name":"MINOR ILLUSION","page":167,"cost":"10 Fortune","effect":"Spell. Cost: 1 Light Bar. Sustainable. You can create an illusion of an object no larger than 2 meters in diameter, centered at any point within 50m of you. This illusion creates no sound, heat, smell, or touch, but otherwise appears real unless the observer succeeds on an Observation Test against the Magic Arts result made when using this spell. You may relocate the spell within range whenever you sustain the spell. Amp: 1 Light Bar. The illusion can cover an area up to 10 meters in diameter."},{"id":"college-of-light-major-illusion","name":"MAJOR ILLUSION","page":167,"cost":"20 Fortune","effect":"Spell. Cost: 1 Light Bar. 1 Force Bar. Sustainable. Requires Minor Illusion and 2 other abilities from the College of Light. You can create an illusion of an object no larger than 2 meters in diameter, centered at any point within 50m of you. Unlike minor illusion, this also includes sound. The image appears real unless the observer succeeds on an Observation Test against the Magic Arts result made when using this spell. This image lasts for as long as the caster spends a Backup Action each Round maintaining the image, during which time it may change as desired by the caster. You may relocate the spell within range whenever you sustain the spell. Amp: 1 Light Bar. The illusion can cover an area up to 10 meters in diameter. Amp: 1 Fire Bar. The illusion also includes heat. Amp: 1 Chemical Bar. The illusion also includes taste and smell. Amp: 1 Force Bar. The illusion includes touch, though it cannot support more than 1 kg of weight or exert or resist a comparable force."},{"id":"college-of-light-blinding-flash","name":"BLINDING FLASH","page":167,"cost":"20 Fortune","effect":"Spell. Cost: 1 Light Bar. Sustainable. Requires 5 other choices from the College of Light. You create a series of blinding flashes. While sustaining this spell, you may take an Interrupt Action to roll Magic Arts vs Aegis of a target within 50m. On a Success the target gains two instances of Dulled on all tests involving vision until the end of their turn. Any target with closed eyes gains +5 Aegis on that test. Amp: For each Light Bar added, you may add one additional Dulled."},{"id":"college-of-light-light-mastery","name":"LIGHT MASTERY","page":167,"cost":"20 Fortune","effect":"Requires 5 other choices from the. College of Light. Free Action. Once per turn, you may spend 1 Grit to add 1 Light Bar to an Amp without harmonizing for that bar."}]},{"id":"alchemical-college","label":"Alchemical College","items":[{"id":"alchemical-college-somatic-poison","name":"SOMATIC POISON","page":168,"cost":"10 Fortune","effect":"Spell. Compound. Cost: 1 Chemical Bar. You synthesize a dangerous poison from common metabolites in people’s bodies, causing harm. Roll Magic Arts vs Aegis of a target within 10m. On a Success, the target takes 2d6 physical damage a turn for the next 3 turns. This damage ignores Armor. Amp: 1 Chemical Bar. The spell does an additional 2d6 damage a Round. Amp: 1 Chemical Bar. The target continues taking damage each hour after the spell effect. If the target succeeds on a physicality test against the initial result of this spell they take no damage (but the effect continues). A Science test of someone providing medical care may replace the physicality test. On a Dynamic or Critical Success, the spell effect ends. Amp: 1 Chemical Bar. The target takes -3 guard and gains a Consequence until the spell effect ends."},{"id":"alchemical-college-psychotropic-poison","name":"PSYCHOTROPIC POISON","page":168,"cost":"10 Fortune","effect":"Spell. Compound. Cost: 1 Chemical Bar. You synthesize a poison targeting people’s mind from the metabolites in their bodies. Roll Magic Arts vs Aegis of a target within 10m. On a Success, the target takes 2d6 Animity damage a turn for the next 3 turns. Amp: 1 Chemical Bar. The spell does an additional 2d6 damage a Round. Amp: 1 Chemical Bar. The target continues taking damage each hour after the spell effect. If the target succeeds on a physicality test against the initial result of this spell they take no damage (but the effect continues). A Science test of someone providing medical care may replace the physicality test. On a Dynamic or Critical Success, the spell effect ends. Amp: 1 Chemical Bar. The target takes -3 Vigilance and gains a Consequence until the spell effect ends."},{"id":"alchemical-college-ditty-of-restoration","name":"DITTY OF RESTORATION","page":168,"cost":"10 Fortune","effect":"Ditty. You can fix minor physical or corrosion damage to a touched object, or make an older item appear new. Repair 3 damage to an object in T range. An object affected by the ditty of restoration is immune to its effect until it takes new damage—future castings can only repair damage since the last casting. A character with this ditty decreases the TN to make repairs by 5."},{"id":"alchemical-college-stable-compounds","name":"STABLE COMPOUNDS","page":169,"cost":"10 Fortune","effect":"As a Downtime Action, you may use the any spell with the compound keyword to synthesize 5 doses of compounds with the effect of the spell (including any amps you can add) and place them in syringes. As a Main Action, anyone with the syringe may attempt to inject the compound. Roll Melee Combat (+Agility) against the Guard of a target in T range. On a Success, target is injected with the compound and suffers its effects as below. If not successful, the compound is not used up. No roll is required to inject it into a willing target, additionally, you or the wielder may spend 1 Grit to inject a willing target as an Interrupt Action. Any unused compounds become inert at the beginning of the next Downtime."},{"id":"alchemical-college-purify-metabolism","name":"PURIFY METABOLISM","page":169,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Sustainable. You render inert any foreign chemicals in a single living target within 10m, or a collection of living creatures with a total mass of less than 100kg. Any ongoing effects due to drugs, poisons or other chemical effects on the targets end."},{"id":"alchemical-college-arcane-metabolism","name":"ARCANE METABOLISM","page":169,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Sustainable. You use magic to power the metabolism of a single living target within 10m. The target gains 2 temporary Health and Animity (take damage from temporary Health and Animity first); and while under the effect of this spell the target does not need to breathe, eat, drink, or sleep. Relying on this spell for long periods of time is dangerous, however—for each day a target skips their basic needs while under this effect, they reduce their max Health and Animity by one. This penalty can be reset by taking a Downtime Action to recover (assuming you have access to the necessities you skipped). Amp: 1 Chemical Bar. While under the effect of the spell, the target gains Reliable 3 on all Physicality tests."},{"id":"alchemical-college-determine-composition","name":"DETERMINE COMPOSITION","page":169,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Sustainable. You’ve learned to divine the chemical composition of an object by seeing how it reacts to alchemical magic. Choose an object or area within 10m no larger than 1 meter in diameter. Make a TN 8 Science Test, on a Success you know the basic chemical composition of the object or area. Higher results reveal more information about trace components or rare compounds (such as poisons or pharmaceuticals)"},{"id":"alchemical-college-corrosive-defense","name":"CORROSIVE DEFENSE","page":169,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Sustainable. You cover yourself in a protective layer of acid, punishing anyone or anything that touches you with a splatter of acid. Anyone who does damage to you at range T, or anyone you do damage to with a Melee Attack takes 2d6 points of chemical damage. Amp: 1 Chemical Bar. Reduce all incoming chemical or poison damage by five. Amp: 1 Fire Bar. Attackers take an additional 1d6 fire damage per turn for the next 5 Rounds. Amp: 1 Chemical Bar. You can choose a target in T range other than yourself as the benefit of your corrosive defense."},{"id":"alchemical-college-arcane-refinement","name":"ARCANE REFINEMENT","page":169,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Sustainable. You process up to 10kg of material in T range, removing any impurities in the material and increasing its strength. Using this spell gives +3 on any tests to build an object. Amp: 1 Chemical Bar. Objects created with this spell become extra durable, gaining 3 Armor on any attacks directly targeting them. If the target would already have 3 or more Armor normally, it instead gains +1 Armor. This does not apply to Armor an object grants to its wearer or occupants. Amp: 1 Force Bar. You can separate trace material from a large quantity of impure material. You may target up to 1000kg of raw material, and extract up to 10kg of target material from it. If the material is not readily separable (e.g. extracting metal from ore, or wiring from a complicated device), this spell instead does 1 point of damage per Round until the target is destroyed enough to separate the material from it."},{"id":"alchemical-college-alchemical-pharmacist","name":"ALCHEMICAL PHARMACIST","page":169,"cost":"10 Fortune","effect":"Requires Stable Compounds. You can synthesize drugs that people need. Using a Downtime Action, you may make a Science test vs TN 10. On a Success, everyone in the Community regains 2 Health. You may instead use this ability to gain up to 2 Fortune worth of drugs on a successful Test (see \"Drugs\" on pg 102)"},{"id":"alchemical-college-acidify","name":"ACIDIFY","page":170,"cost":"10 Fortune","effect":"Spell. Cost: 1 Chemical Bar. You turn two liters of liquid within 20m into a powerful acid. Anyone who comes in contact with it takes 6d6 acid damage and reduces their physical Armor by 3 until it is repaired. Amp: 1 Force Bar. You spray the acid through the air. You may split the damage dice across any number of targets within 20m by making a Magic Arts test vs the Aegis of each target (split the dice before rolling Magic Arts). Anyone who takes damage takes the Armor penalty. Amp: For each additional Chemical Bar used on this Amp casting this spell, increase the total damage by 2d6 and reduce physical Armor by an additional 2 points."},{"id":"alchemical-college-augment-fuel","name":"AUGMENT FUEL","page":170,"cost":"10 Fortune","effect":"Spell. Cost: 2 Chemical Bars. Sustainable. You increase the energy released from fuel, increasing it’s potency. Any gun or rocket fired within 50m of you, or any fire or explosion that occurs within 50m of you, has its damage increased by 1d6. Any vehicle has its top Speed increased by one, however it takes 1 physical damage each Round this is in effect. Amp: 1 Chemical Bar. You may select what sources are affected by this spell. Amp 1 Fire Bar. Increase damage from fire and explosions by 3d6."},{"id":"alchemical-college-synthesize-stimulants","name":"SYNTHESIZE STIMULANTS","page":170,"cost":"20 Fortune","effect":"Spell. Cost: 1 Chemical Bar. Compound. Requires 3 other choices from the Alchemical College. You can synthesize a variety of stimulants from common metabolites in people’s bodies. Roll Magic Arts vs TN 12 (or Aegis if they’re unwilling) of a target within 10m. On a Success, the target gains +5 initiative and +3 Guard and Vigilance for the next 5 Rounds. Amp: 1 Chemical Bar. The target gains Armor +1 while this spell is in effect. If this is the first time the character has been affected by this spell this Act Phase, the character heals 2d6 Health and Animity damage. Amp: 1 Chemical Bar. The character gains Augment 2 on all tests while this spell is in effect. Amp: 1 Chemical Bar. This spell can affect a number of targets within 10m equal to 2 plus your ranks in Magic Arts. Amp: 1 Mana Bar. This spell becomes sustainable. The effects of this spell last for 5 Rounds after the spell stops being sustained. For every hour a character is under this effect each day (cumulative across multiple castings), they take 1d6 Health and Animity damage."},{"id":"alchemical-college-ditty-of-corrosion","name":"DITTY OF CORROSION","page":170,"cost":"10 Fortune","effect":"Ditty. You cause corrosion or damage to the touched target. Make a Magic Arts vs Aegis Test against a target in T range. On a Success do 2d6 damage and reduce the target's Armor by one until the next Downtime."},{"id":"alchemical-college-disintegrate","name":"DISINTEGRATE","page":170,"cost":"20 Fortune","effect":"Spell. Cost: 2 Chemical Bars. Requires. 3 other choices from the Alchemical College. You dissolve the chemical bonds holding a piece of matter together, turning it into dust and gas. Roll Magic Arts vs Aegis for a target within 10m, on a Success, you do 8d6 damage. If this reduces the target to zero Health, they gain an immediate additional Consequence. If this reduces a nonliving object to zero Health, the object is destroyed. Amp: 1 Chemical Bar. For each additional bar spent on this Amp, do +3d6 damage."},{"id":"alchemical-college-alchemist-s-stone","name":"ALCHEMIST'S STONE","page":170,"cost":"20 Fortune","effect":"Spell. Sustainable. Cost: 2 Chemical. Bars. Requires 3 other choices from the Alchemical College. Successfully casting this spell requires a TN 12 Magic Arts Test. Upon casting or sustaining this spell, you can precipitate carbon from the air around you into 2 kg of graphite. This can be in any shape you desire. While this spell is sustained, this can be used to create cover, granting +3 Guard to a target of the caster's choice within 10m as an Interrupt Action. The graphite created in this way is real and nonmagical, and can be used to make structures, sculptures, or more. Amp: 1 Fire Bar. You may ignite the excess oxygen produced by this spell, creating small explosions. When casting or sustaining this spell, you may do 2d6 fire damage to a target within T range of the alchemist's stone you’re creating. Anyone making a Melee Attack against a target you’re providing cover for also takes 2d6 fire damage each time they make an attack. Amp: 1 Force Bar. You levitate the created stone in the air, providing a more substantial block of attacks. When you use this spell to give a bonus to guard, the target also receives +2 Armor. Amp: 1 Force Bar, 1 Fire Bar. Instead of creating graphite, you create diamond, albeit flawed. Anyone protected by this spell gains an additional +3 Guard and +4 Armor."},{"id":"alchemical-college-the-mystic-poultices","name":"THE MYSTIC POULTICES","page":171,"cost":"20 Fortune","effect":"Spell. Cost: 1 Chemical Bars. 1 Mana. Bar. Compound. Requires 3 other choices from the Alchemical College. By tinkering with the innate magic in everything, the poultices created by this spell blend mana and chemistry to provide powerful boons. This sort of magic is dangerous, and on a Dynamic Failure this spell may draw negative attention from spirits (and sometimes even the gods). Roll Magic Arts vs TN 12 (or Aegis if they’re unwilling) of a target within T range as you anoint them with the poultice as part of the casting. On a Success, the target gains the following effect based on their magical tradition: ※ Arcane—The next harmonize action the character takes within the next 5 Rounds is a Free Action. ※ Sublime—The character may immediately gain the effect of another meditation they know for the next 5 Rounds (this does not count against their limit of meditations). ※ Divine—The next spell the target casts has its dissonance reduced by 1. ※ No Magic Tradition—The target ignores the effect of Dulled for the next 5 Rounds. If this is the first time this act mode they have been targeted by this spell, they regain 2 Grit. Amp: 1 Mana Bar. Instead of the normal effect, the target instead loses the ability to use magic for 5 Rounds. A character may negate this effect by spending 5 Grit. Amp: 2 Chemical Basr, 2 Mana Bars. The effect lasts until used, or when 1 hour elapses (whichever happens first)"},{"id":"alchemical-college-alchemical-mastery","name":"ALCHEMICAL MASTERY","page":171,"cost":"20 Fortune","effect":"Requires 5 other choices from the. Alchemical College. Free Action. Once per turn, you may spend 1 Grit to add 1 Chemical Bar to a Amp without harmonizing for that bar."}]},{"id":"college-of-storm","label":"College of Storm","items":[{"id":"college-of-storm-shocking-ditty","name":"SHOCKING DITTY","page":171,"cost":"10 Fortune","effect":"Ditty. You create a jolt of lightning at a target within 10m. If used as an attack, Roll Magic Arts vs Aegis, on a Success do 2d6 Electrical damage, ignoring Armor."},{"id":"college-of-storm-grounding-ditty","name":"GROUNDING DITTY","page":171,"cost":"10 Fortune","effect":"Ditty. Sustainable. You ground the touched target, negating any electrical charge on it and protecting it from electrical damage: gain 5 Armor against Electrical damage until the end of the next Round. Amp: For each Storm Bar used for this Amp, you may add an additional target."},{"id":"college-of-storm-aurora","name":"AURORA","page":171,"cost":"10 Fortune","effect":"Spell. Cost: 1 Storm Bar. Sustainable. You charge the particles in the air around you, illuminating the air and its movements around you. You may use this to distract enemies and protect your allies: increase the Guard of any creature you choose within 50m by +2 as long as Aurora is sustained, and any attack relying on an electronic sensor to target them (including any remotely targeted attacks or attacks by drones or vehicles) gains one instance of Dulled. You may change the target of the spell when you sustain this spell. Amp: You may spend 1 Storm Bar to use the aurora to overwhelm electronic devices. Any devices (including drones and vehicles) you choose take 1d6 electric damage each Round."},{"id":"college-of-storm-static","name":"STATIC","page":172,"cost":"10 Fortune","effect":"Cost: 1 Storm Bar. Sustainable. You create electromagnetic noise that interferes with wireless communications. The range of all devices (see \"Range\" on pg 50) within 50m of you is reduced to 10m, and all tests requiring wireless control whose target or originator is within 50m gain one instance of Dulled. A character may make a Tech test opposed by your Magic Arts as a Backup Action to negate the range penalty. Amp: For each additional Storm Bar added, you may add one additional instance of Dulled to any wireless actions. You may choose which devices are affected by this Amp. Amp: 1 Storm Bar. You may increase the range of this spell to 100m, and the range of all devices are reduced to T."},{"id":"college-of-storm-backup-generator","name":"BACKUP GENERATOR","page":172,"cost":"10 Fortune","effect":"Spell. Cost: 1 Storm Bar. Sustainable. You provide energy to an electrical device, sustaining it and providing power. It can maintain its function indefinitely, and gains Augment 3 on all relevant Tests; however, on a Dynamic Failure it becomes inoperable. You can spend a Downtime Action to provide power for your Community. Treat this as the Side Gig (see pg 37) Downtime Action, except the GM gains no Grit and all Downtime Actions requiring power gain Augment 3."},{"id":"college-of-storm-lightning-bolt","name":"LIGHTNING BOLT","page":172,"cost":"10 Fortune","effect":"Spell. Cost: 1 Storm Bar. Pick a target within 50m. Roll Magic Arts vs Aegis; on a Success do 5d6 Electrical damage, ignoring Armor. Amp: For each additional Storm Bar used casting this spell, target one additional target within 20m of the original target."},{"id":"college-of-storm-lightning-storm","name":"LIGHTNING STORM","page":172,"cost":"10 Fortune","effect":"Spell. Cost: 2 Storm Bars. Sustainable. Pick a target within 50m. Everyone within 10 m of target take 2d6 Electrical damage for each Round the spell is sustained as long as they remain in range. Amp: For each additional Storm Bar used casting this spell, do +2d6 damage."},{"id":"college-of-storm-magnetism","name":"MAGNETISM","page":172,"cost":"20 Fortune","effect":"Cost: 2 Storm Bars. Sustainable. You create a strong magnetic field, manipulating ferrous materials on or around your target to interfere with their function. As an interrupt while sustaining this spell, you may pick a point withing 50m. Make a Magic Arts vs Aegis Test against all targets withing 5m of that point. Any target that fails gains one instance of Dulled until the start of your next turn. Add an additional instance of Dulled if they are using or wearing substantial amounts of metal (this includes drones and other devices made substantially of metal). Amp: For each Storm Bar used for this Amp, you may add an additional instance of Dulled to this spell. Amp: Objects affected by this spell become dangerous projectiles. Everyone within 5m of the targeted point takes 1d6 physical damage for each Storm Bar used on this Amp."},{"id":"college-of-storm-seizure","name":"SEIZURE","page":173,"cost":"20 Fortune","effect":"Spell. Cost: 1 Storm Bar. Sustainable. You manipulate the electricity within the brain of a living creature within 10m. Roll Magic Arts vs Aegis; on a Success, the target takes 1d6 Metabolic damage and cannot take any actions until the start of your next turn. Each Round you sustain this spell you may repeat this effect (rolling again). Once a creature resists the effects of this spell it cannot be affected again by this casting. Amp: 1 Storm Bar. You may crudely control the movements of a creature under the effects of this spell. On the targets turn you may move them 10m. Amp: 1 Storm Bar. You may target two additional creatures for each Storm Bar used for this Amp."},{"id":"college-of-storm-storm-mastery","name":"STORM MASTERY","page":173,"cost":"20 Fortune","effect":"Requires 5 other choices from the. College of Storm. Free Action. Once per turn, you may spend 1 Grit to add 1 Storm Bar to a Amp without harmonizing for that bar."}]},{"id":"college-of-fire","label":"College of Fire","items":[{"id":"college-of-fire-wreath-of-flame","name":"WREATH OF FLAME","page":173,"cost":"10 Fortune","effect":"Ditty. Sustainable. You cover a melee weapon or other held object with flames until the end of your next turn. While on fire, T he it does an additional 1d6 Fire damage on any attacks. If it is vulnerable to fire, it takes that damage too."},{"id":"college-of-fire-temperate-ditty","name":"TEMPERATE DITTY","page":173,"cost":"10 Fortune","effect":"Ditty. Sustainable. You absorb excess heat from an object, spell, effect, or ability. The object is cooled to ambient temperature, and protected from heating. One target gains 5 Armor from Fire and cold damage until the end of the next Round. Amp: For each Fire Bar used for this Amp, you may add an additional target."},{"id":"college-of-fire-heat-shield","name":"HEAT SHIELD","page":173,"cost":"10 Fortune","effect":"Spell. Cost: 1 Fire Bar. Sustainable. Requires Temperate Ditty. You wreathe yourself in a shield of fire, protecting you from heat. Reduce all incoming fire and cold damage by three. Anyone who does damage to you at range T takes 3d6 fire damage. Amp: 1 Fire Bar. For each Fire Bar spent on this Amp, reduce incoming fire and cold damage by an additional 5 points. Amp: 1 Fire Bar. Your unarmed attacks do 3d6 fire damage. Amp: 1 Fire Bar. For each Fire Bar spent on this Amp, increase all damage done by this spell by 1d6. Amp: 1 Fire Bar. You can choose a target in T range other than yourself as the benefit of your fire shield."},{"id":"college-of-fire-cauterize","name":"CAUTERIZE","page":174,"cost":"10 Fortune","effect":"Ditty. You may pick a target within T range that has taken a Consequence from being reduced to zero Health. Remove that Consequence, but the target takes 3 Irresistible Health and Animity damage."},{"id":"college-of-fire-hearth","name":"HEARTH","page":174,"cost":"10 Fortune","effect":"Spell. You create warmth and easy availability of fire and flame for your Community. Using a Downtime Action, increase all Grit, Health, and Animity gains for members of your Community by 1 during that Downtime."},{"id":"college-of-fire-fire-ball","name":"FIRE BALL","page":174,"cost":"10 Fortune","effect":"Spell. Cost: 1 Fire Bar. Requires. Flame Burst. Choose a point within 50 m and roll Magic Arts against the Aegis of all targets within 10m of that point (roll once against all targets). On a Success, each target takes 3d6 Fire Damage. Amp: For each additional Fire Bar used casting this spell, do +2d6 damage. Amp: 1 Fire Bar. Only targets you choose take damage. Amp: 1 Chemical Bar. You create a noxious smoke cloud with the explosion. Those who take damage also lose their next Main Action."},{"id":"college-of-fire-hot-potato","name":"HOT POTATO","page":174,"cost":"10 Fortune","effect":"Spell. Cost: 1 Fire Bar. Sustainable. Choose an item within 50m. If attended, it resists with its owner’s Aegis; otherwise treat as Aegis of 8. On a Success, anyone touching the object takes 3d6 Fire damage. Anyone who takes damage from this must immediately drop the item if possible. At GM discretion, this effect may destroy or render inoperable the chosen item. Amp: 1 Chemical Bar. The caster can choose for an affected item to either be protected from the effects of this spell or rendered immediately inoperable until repaired. Amp: 1 Fire Bar. For each Fire Bar used on this Amp, choose two additional items within 50m. Amp: 1 Fire Bar. For each Fire Bar used on this Amp, do an additional 1d6 damage."},{"id":"college-of-fire-fire-mastery","name":"FIRE MASTERY","page":174,"cost":"20 Fortune","effect":"Requires 5 other abilities from the. College of Fire Free Action. Once per turn, you may spend 1 Grit to add 1 Fire Bar to an Amp without harmonizing for that bar."},{"id":"college-of-fire-flame-burst","name":"FLAME BURST","page":174,"cost":"10 Fortune","effect":"Spell. Cost: 1 Fire Bar. Choose a target within 50m and roll Magic Arts vs Aegis. On a Success, deal 6d6 damage. Amp: For each additional Fire Bar used casting this spell, deal +3d6 damage."}]},{"id":"mantle-of-authority","label":"Mantle of Authority","items":[{"id":"mantle-of-authority-voice-of-assurance","name":"VOICE OF ASSURANCE","page":175,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You speak an assuring suggestion to a target within 10m. Decrease the value of any Ask you make to the target by 3. If they do what you suggest, any skill tests they make before your next turn towards your suggestion gain +1 dice and are Inspired. If they reject your suggestion, both you and the target take 2 Animity damage."},{"id":"mantle-of-authority-incantation-of-command","name":"INCANTATION OF COMMAND","page":176,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You exert your sacred power over a haunt, spirit, or demon within 10m. Reduce their Aegis by 5 until the end of your next turn."},{"id":"mantle-of-authority-grant-authority","name":"GRANT AUTHORITY","page":176,"cost":"10 Fortune","effect":"Spell. Dissonance 3. Interrupt. You impart authority to someone else within 50m. Spend 1 Grit to give the target +2 dice on all Influence tests and +2 on all defenses for 10 minutes, or until you cast another spell or make an Influence test. While this effect is active, you may allow them to spend your Grit as if it were their own."},{"id":"mantle-of-authority-steward","name":"STEWARD","page":176,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. Pick any number of targets within 50m. You gain Inspired and Reliable 3 on any action made to assist them for the next five Rounds. For the next 24 hours, if you take any action against them or intentionally allow them to come to harm, you take 3d6 Animity damage."},{"id":"mantle-of-authority-natural-leader","name":"NATURAL LEADER","page":176,"cost":"20 Fortune","effect":"Spell. Interrupt. Dissonance 1. Requires. 3 other abilities from the Mantle of Authority. Make a Magic Arts test against TN 10. On a Success, all allies (not including you) within 50m gain +1d6 on all skill tests and +1 defenses until the beginning of your next turn, and you gain +1 dice on Influence tests. You or any target may spend any amount of Grit; for each Grit spent increase the duration by 1 Round."},{"id":"mantle-of-authority-proclaim-law","name":"PROCLAIM LAW","page":176,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Requires 3 other. abilities from the Mantle of Authority. Pick one of your Values and state an edict upholding it. Make a Magic Arts test vs Aegis for anyone who hears your edict within 50m. On a Success, they take 4d6 Animity damage the first time they violate the edict within the next day."},{"id":"mantle-of-authority-oath","name":"OATH","page":176,"cost":"10 Fortune","effect":"Spell. Dissonance 4. You bind one or more willing parties within 10m, which can include yourself, to a specific Oath. Each participant spends an agreed amount of Grit. For each Grit spent by any participant, gain a pool of Grit usable by any member to uphold the oath or prevent it from being broken. Any participant can refill the pool by spending Grit. If a participant breaks the oath, the oath-breaker immediately takes a number of dice of Animity damage equal to the amount each participant spent, and the effect ends for all participants."}]},{"id":"mantle-of-cultivation","label":"Mantle of Cultivation","items":[{"id":"mantle-of-cultivation-grow-plants","name":"GROW PLANTS","page":176,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You cause plants of your choice within 100m range to grow at ten times their normal rate. Fruit and Vegetable plants produce an abundance of food. If you use this ability and make a Magic Arts test as part of the Side Gig (pg 37) Downtime Action, you gain 1 additional Fortune. If you have the Community Garden (pg 137) resource, you may use a Downtime Action to decrease the cost of lifestyle maintenance for everyone in your Community by 1 and decrease the GM's Grit by 2."},{"id":"mantle-of-cultivation-verdant-boon","name":"VERDANT BOON","page":177,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You endow an ally with strength and resilience. They gain 2 Armor and 2 Adamant until the end of the scene. Any character may only be under the effect of one instance of Verdant Boon at a time. Special: You may cast this spell as a Downtime Action. If you do so, any member of your Community who takes a Downtime Action with you gains 4 Armor and 4 Adamant until the start of the next Downtime."},{"id":"mantle-of-cultivation-grow-strong","name":"GROW STRONG","page":177,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You imbue an ally within 10m range with vigor and ability. They gain +1d6 on all tests linked to Brawn or Agility until the end of your next turn, and gain Augment 1 on all such tests. You or they may spend one Grit to extend the duration of the spell by one Round (this may be done multiple times)"},{"id":"mantle-of-cultivation-nurture","name":"NURTURE","page":177,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You heal and strengthen a target within 10m. They heal 4 Health. A character may only benefit from the nurture spell once between the end of each Downtime. Special: You may cast this spell as a Downtime Action. If you do so, any member of your Community may take a Downtime Action with you to heal 8 Health damage. If this would bring a character to full Health, they increase their max Health by the remainder until the end of the next Downtime."},{"id":"mantle-of-cultivation-grow-the-community","name":"GROW THE COMMUNITY","page":177,"cost":"10 Fortune","effect":"You may take a Downtime Action to reduce the cost of one Community paradigm ability by the number of abilities you have in this paradigm (this can reduce the cost to a minimum of one Fortune). If you do so, regain 1 Animity and Grit."},{"id":"mantle-of-cultivation-peace-and-calm","name":"PEACE AND CALM","page":177,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You provide the mental space necessary for a character to thrive and grow. They heal 4 Animity damage. A character may only benefit from the Peace and Calm spell once between the end of each Downtime. Special: You may cast this spell as a Downtime Action. If you do so, any member of your Community may take a Downtime Action with you to heal 8 Animity damage. If this would bring a character to full Animity, they increase their max Animity by the remainder until the end of the next Downtime. Additionally, the GM must spend 5 more Grit to activate a Community Impulse until the end of the next Downtime."},{"id":"mantle-of-cultivation-ring-of-rescue","name":"RING OF RESCUE","page":177,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Interrupt. Make a Magic Arts test. Any allies within 10m may use the result of your roll instead of their guard until the end of your next turn. You or any target may spend any amount of Grit; for each Grit spent increase the duration by 1 Round."},{"id":"mantle-of-cultivation-tireless-cultivator","name":"TIRELESS CULTIVATOR","page":177,"cost":"20 Fortune","effect":"Requires Nurture, Peace and Calm, and. 1 other ability from the Mantle of Cultivation. When you use the Nurture or Peace and Calm spells, you may increase the dissonance by 1 to target a character who has already been targeted by those effects a second time (they may not be targeted by the ability a third time)"},{"id":"mantle-of-cultivation-vigorous-steward","name":"VIGOROUS STEWARD","page":177,"cost":"30 Fortune","effect":"Spell. Interrupt. Dissonance 2. Requires. 6 abilities from the Mantle of Cultivation. You may use this ability to target a character who has taken a Downtime Action to gain the benefits of your abilities from this paradigm. Spend any amount of Grit. For each point of Grit spent, increase their Guard, Vigilance, and Aegis by 2 until the beginning of their next turn. This may be done after learning the result of a test targeting them—apply this spell before resolving that effect. When the GM spends Grit to trigger a Community Impulse, the player may immediately spend any amount of Grit. The GM must spend Grit equal to twice the amount of Grit spent or the Impulse is not triggered."}]},{"id":"mantle-of-death","label":"Mantle of Death","items":[{"id":"mantle-of-death-frailty-of-life","name":"FRAILTY OF LIFE","page":178,"cost":"10 Fortune","effect":"Spell. Dissonance 2. You pull an injured target closer to death. Choose a target within 10m. On a successful Magic Arts vs Aegis test, they take damage equal to the current amount of damage they’ve taken."},{"id":"mantle-of-death-killer-s-eye","name":"KILLER’S EYE","page":178,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. You make a blow land with extra impact. After witnessing a successful attack within 100m, you may cast this spell to give it Augment 5."},{"id":"mantle-of-death-hardened","name":"HARDENED","page":178,"cost":"10 Fortune","effect":"Your intimacy with the domain of death has desensitized you to experiences others might find disturbing. Gain Adamant 2."},{"id":"mantle-of-death-champion-of-war","name":"CHAMPION OF WAR","page":178,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. A target you can see within 50m gains +2 Guard and Augment 2 on all Melee and Ranged Combat tests for 3 Rounds."},{"id":"mantle-of-death-imbue-prowess","name":"IMBUE PROWESS","page":178,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. You call upon sacred power to imbue a target with skill. The target may use your ranks in Magic Arts instead of Ranged or Melee Combat skills tests for their next three turns."},{"id":"mantle-of-death-mortality-s-chains","name":"MORTALITY’S CHAINS","page":178,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You target a spirit, elemental, undead, or construct within 50m. Roll Magic Arts vs Aegis of the target; on a Success the target takes 6d6 Physical Damage and 2d6 Animity Damage."},{"id":"mantle-of-death-accidental-harm","name":"ACCIDENTAL HARM","page":178,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. You call on your power to will the universe to become more hazardous to a target. Make a Magic Arts vs Aegis of a target you can see within 50m. On a Success, the next time within the next day they are in a hazardous situation where they might take damage or get a Dynamic Failure on a Test that could conceivably lead to harm, they take 3d6 Physical damage in addition to the normal effects."},{"id":"mantle-of-death-famine","name":"FAMINE","page":178,"cost":"20 Fortune","effect":"Spell. Downtime Action. Dissonance. 5. Requires 3 other abilities from the Mantle of Death. You call misFortune down on a target. As a Downtime Action, you may target a character. Make a Magic Arts test against their Aegis (if an individual) or against a TN equal to Power x2 +12 (for a Faction or Community). On a Success, the target gains a Consequence until the next Downtime. Whenever a PC uses this ability, the GM gains 10 Grit."},{"id":"mantle-of-death-contest-of-martial-skill","name":"CONTEST OF MARTIAL SKILL","page":179,"cost":"20 Fortune","effect":"Spell. Dissonance 1. Requires 3 other. abilities from the Mantle of Death. You will combatants around you to a contest of skill. Make a Magic Arts Test against the Aegis of all targets within 50m (willing targets may choose to be automatically affected by this spell). All affected targets take a -5 penalty to their Guard. Whenever a character affected by this spell makes a Melee or Ranged Combat test, that result becomes their Guard until the beginning of their next turn."},{"id":"mantle-of-death-pestilence","name":"PESTILENCE","page":179,"cost":"20 Fortune","effect":"Spell. Dissonance 3. Requires 3 other. abilities from the Mantle of Death. You inflict a supernatural disease upon a target within T range on a successful Magic Arts vs Aegis test. The target gains an immediate Consequence, and each Round must make a Physicality test opposed by your Magic Arts skill. On a Failure they take 2d6 damage, on a Success they take no further damage for now (on a Dynamic or Critical Success, the spell immediately ends, removing the Consequence from this spell). At the end of each Downtime, an affected target must make a Physicality test vs your Magic Arts Skill as above. If they took the Recover action during Downtime they gain a +5 on this test, if someone took the provide care action on their behalf they may replace the Physicality test with a Science or Magic Arts test. On a Dynamic Failure, this spell passes on to someone else the target had close contact with (GM's decision)—they are treated as if they were targeted by this spell in an identical matter to the original target. Whenever a PC uses this ability, the GM gains 10 Grit."},{"id":"mantle-of-death-parole-death","name":"PAROLE DEATH","page":179,"cost":"30 Fortune","effect":"Spell. Dissonance 4. Requires 6 other. abilities from the Mantle of Death. You allow an injured target within 50m range to continue onward even in the face of extreme injury. Target gains 1 Health and loses the Unconscious condition if it has it, and gains a Parole Death Progress Track starting at the current amount of damage they’ve taken to their Health track and with a max value equal to twice their normal max Health. Any further damage the target takes is applied to the Parole Death track before it is applied to Health."}]},{"id":"mantle-of-passion","label":"Mantle of Passion","items":[{"id":"mantle-of-passion-divine-desire","name":"DIVINE DESIRE","page":180,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. Roll Magic Arts vs Aegis on a target you are engaged in conversation with. On a Success, you learn the Value, Impulse, goal, or positive Relation that is most salient to them at the moment. (Note, Asks that are lined up with the Values, Impulses, and Goals of a target become easier (see \"Asks\" on pg 44))"},{"id":"mantle-of-passion-entice-desire","name":"ENTICE DESIRE","page":180,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You convince a target to do something related to one of their wants or desires (even if it conflicts with other goals or Values). Roll Magic Arts vs Aegis on a target within 50m. On a Success, decrease the Ask of any request that advances one of their Values, Impulses, goals, or positive relationships by 6."},{"id":"mantle-of-passion-fill-life-with-passion","name":"FILL LIFE WITH PASSION","page":180,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. Choose a target within 10m (including yourself) that has taken an action to advance an Impulse, Value, goal, or Relation with a Regard greater than 5. They gain 2 Grit and 2 Animity. This may only be done once per character per session."},{"id":"mantle-of-passion-love-and-kindness","name":"LOVE AND KINDNESS","page":180,"cost":"10 Fortune","effect":"Spell. Dissonance 3. Interrupt. Once per session per Relation, upon meeting a Relation with a Regard greater than 5, you regain 3 Animity."},{"id":"mantle-of-passion-many-friends","name":"MANY FRIENDS","page":180,"cost":"10 Fortune","effect":"You gain 1 Fortune for every Relation you have with a Regard of ten or higher. This applies to your current Relations as well as any new Relations (you do not lose this Fortune if the Base Regard drops, however you do not gain it again if you raise their Regard back up). Whenever you take the Interact with Relation Downtime Action (see pg 37), gain 1 Grit."},{"id":"mantle-of-passion-follow-passion","name":"FOLLOW PASSION","page":180,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. Spend 1 Grit to choose a target within 10m (including yourself) that has taken an action to advance an Impulse, Value, goal, or Relation with a Regard greater than 5. The target gains +2 dice on any tests involved in that action and the roll becomes Inspired."},{"id":"mantle-of-passion-love-is-life","name":"LOVE IS LIFE","page":180,"cost":"20 Fortune","effect":"Requires 3 other abilities from the. Mantle of Passion. Gain 2 Additional Values and +2 Max Grit."},{"id":"mantle-of-passion-bond-of-love","name":"BOND OF LOVE","page":180,"cost":"20 Fortune","effect":"Spell. Dissonance 3. Requires 3 other. abilities from the Mantle of Passion. Choose a target within T range with a Regard towards the caster of 8 or higher, or a willing PC who both players agree is a good friend or better. Until the next Downtime, either character may spend Grit from each other's pools. When the characters make a teamwork or Group Test together, roll one additional dice and the roll is Inspired."},{"id":"mantle-of-passion-darkness-cannot-dim-a-light","name":"DARKNESS CANNOT DIM A LIGHT","page":180,"cost":"20 Fortune","effect":"Spell. Dissonance 1. Interrupt. Requires. 3 other abilities from the Mantle of Passion. If you have not broken any of your Values, target within 50m gains Adamant 5 until the start of your next turn. If you target yourself, instead gain Adamant 10."},{"id":"mantle-of-passion-purpose","name":"PURPOSE","page":180,"cost":"30 Fortune","effect":"Spell. Dissonance 2. Interrupt. Requires. 6 other abilities from the Mantle of Passion. You may cast this spell upon accomplishing a major goal (GM discretion), upholding a Value at cost to yourself, or improving the Regard of a Relation above 5. Gain 3 Grit and remove a Consequence."}]},{"id":"mantle-of-justice","label":"Mantle of Justice","items":[{"id":"mantle-of-justice-illuminate-guilt","name":"ILLUMINATE GUILT","page":181,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Roll Magic Arts vs Aegis on a target within 10m. On a Success, you ascertain if they believe they have engaged in violations of the law or their Community's Values recently. As this spell depends on the internal beliefs of the target it is considered unreliable except as a guide for future investigations—some people hold more guilt for being accidentally rude to a friend than others do for robbing a bank!"},{"id":"mantle-of-justice-enact-sentence","name":"ENACT SENTENCE","page":181,"cost":"10 Fortune","effect":"Spell. Dissonance 5. Roll Magic Arts vs Aegis on a target within T range who you believe beyond a reasonable doubt has violated one of your Values. They gain 1 Consequence until they meet a condition you specify (typically restitution or a specific duration). This effect lasts for 1 week, however for each Grit you spend, you may increase the duration by 1 month. If you spend 10 Grit, this effect is instead permanent."},{"id":"mantle-of-justice-victim-s-blessing","name":"VICTIM’S BLESSING","page":181,"cost":"10 Fortune","effect":"Spell. Dissonance 3. Spend 2 Grit and choose a target within T range you believe has been a victim of a violation of one of your Values. They heal 5 Health and 5 Animity damage. A character may only benefit from Victim’s Blessing once between the end of each Downtime."},{"id":"mantle-of-justice-student-of-morality","name":"STUDENT OF MORALITY","page":181,"cost":"10 Fortune","effect":"Gain 2 additional Values. The first time you uphold a Value at cost to yourself each session, heal 3 Animity damage (this applies separately for each Value)"},{"id":"mantle-of-justice-respected-arbiter","name":"RESPECTED ARBITER","page":181,"cost":"10 Fortune","effect":"You help resolve issues in your Community. As long as your Community’s Regard towards you is 4 or higher, the GM must spend an additional 2 Grit to trigger a Community Impulse. Furthermore, you remove 3 GM Grit instead of 2 whenever you take the Deal with a Problem Downtime Action."},{"id":"mantle-of-justice-compel-truth","name":"COMPEL TRUTH","page":181,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Interrupt. Requires. 3 other abilities from Mantle of Justice. Roll Magic Arts vs Aegis on a target within 10m. On a Success they may not lie for 1 minute, though they may attempt to misdirect you at a penalty (they take a -5 penalty on any Deception tests). On a Dynamic Success, they may not attempt to misdirect you; on a Critical Success they may not lie by omission and will blurt out the truth in response to questions."},{"id":"mantle-of-justice-hidden-sun-of-the-guilty","name":"HIDDEN SUN OF THE GUILTY","page":181,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Requires 3 other abilities from Mantle of Justice. You create a blinding light source visible only to those who have violated your beliefs. Choose one of your Values. Roll Magic Arts vs Aegis for all targets within 50m. If you beat their Aegis and they have violated that Value, they take 2d6 Health and Animity damage. For minor infractions, halve the damage; for major infractions, double the damage. You may make an Observation test vs Vigilance against anyone affected by this spell—they take a penalty on their Vigilance equal to half the damage taken. On a Success, you identify them as having been affected by this spell."},{"id":"mantle-of-justice-path-to-absolution","name":"PATH TO ABSOLUTION","page":181,"cost":"30 Fortune","effect":"Spell. Dissonance 5. Requires 6 other. abilities from Mantle of Justice. You touch a willing target who has violated one of your Values. Roll Magic Arts vs TN 10; on a Success, they receive visions of their violation (depending on the Value, this may be images of the harm they’ve inflicted, the beliefs of the community, or simply an overwhelming sense that the Value should be observed). The target takes 4d6 Animity damage and gains the Value as one of their own. Any session they work towards providing restitution towards their violation, they heal 5 Animity damage and gain 3 Grit. If they violate that Value, they immediately take 4d6 Animity damage. This effect lasts until they have made full restitution to their violation or for one year, whichever happens first."}]},{"id":"mantle-of-knowledge","label":"Mantle of Knowledge","items":[{"id":"mantle-of-knowledge-know-the-languages-of-earth","name":"KNOW THE LANGUAGES OF EARTH","page":182,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Choose a target within T range. For 1 hour, or as long as they are within 50m of you (whichever is longer), you understand all languages they speak, and they understand all languages you speak."},{"id":"mantle-of-knowledge-snatch-the-mysteries","name":"SNATCH THE MYSTERIES","page":182,"cost":"10 Fortune","effect":"Spell. Dissonance 4. A favorite of Chosen attempting to quickly study up on a subject, the Chosen touches an object and attempts to learn its secrets. Make a Magic Arts test against a TN of 10. On a Success, treat the Chosen as if they had carefully studied the object for a number of hours equal to their margin of Success (minimum 1)"},{"id":"mantle-of-knowledge-sacred-hedge","name":"SACRED HEDGE","page":182,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You know the dangers of mystical effects and how to protect against them. Roll against target caster’s Aegis (or effect TN). On a Success, increase the Aegis of all allies within 50m by 3 against that magical effect. This lasts until the end of the scene."},{"id":"mantle-of-knowledge-know-weaknesses","name":"KNOW WEAKNESSES","page":182,"cost":"10 Fortune","effect":"Spell. Dissonance 2. Choose a target within 50m of you. Make a Magic Arts test against their Aegis defense; if you succeed you and all allies within 50m get +1 dice on all effects targeting them for the next 10 minutes."},{"id":"mantle-of-knowledge-know-ways","name":"KNOW WAYS","page":182,"cost":"10 Fortune","effect":"Interrupt. Spell. Dissonance 1. Choose a target within 50m of you. Make a Magic Arts test against their Aegis defense; if you succeed you and all allies within 50m get +2 Aegis, Guard, and Vigilance against any effects they initiate until the end of your next turn."},{"id":"mantle-of-knowledge-dangerous-knowledge","name":"DANGEROUS KNOWLEDGE","page":182,"cost":"10 Fortune","effect":"You become inured to even the most disturbing knowledge. You gain Adamant 10 against any Animity damage due to learning uncomfortable facts, exposure to alien forces, or other sources of damage based purely on learning something. This does not apply when it directly affects you—learning about a terrifying creature is one thing; seeing a terrifying creature about to attack you is completely different!"},{"id":"mantle-of-knowledge-know-mind","name":"KNOW MIND","page":182,"cost":"20 Fortune","effect":"Spell. Dissonance 3. Requires 3 other. abilities from the Mantle of Knowledge. Choose a target within 10m. On a successful Magic Arts vs Aegis test, you hear their surface thoughts in your head for as long as you take no other actions besides attuning. On a Dynamic Success, you also know any memories they have of the last day. On a Critical Success, you gain access to any of their memories."},{"id":"mantle-of-knowledge-knowledge","name":"KNOWLEDGE","page":182,"cost":"20 Fortune","effect":"Spell. Interrupt. Dissonance. 3. Requires 3 other abilities from the Mantle of Knowledge. Cast upon failing a Science or Humanities test to know something. You may spend 1 Grit to immediately re-roll, gaining a bonus equal to half your ranks in Magic Arts (round up)"},{"id":"mantle-of-knowledge-seek-answer","name":"SEEK ANSWER","page":183,"cost":"20 Fortune","effect":"Spell. Dissonance 3. Requires 3 other. abilities from the Mantle of Knowledge. You look for knowledge. State a simple question that you do not know the answer to and make a Magic Arts test vs TN 10. If you succeed, you learn of the existence and the location of any object within 100m that could help answer your question. If the question could be answered by a person within 100m, compare your result to their Aegis. If your roll beat their Aegis, you learn of their existence and location."},{"id":"mantle-of-knowledge-divination","name":"DIVINATION","page":183,"cost":"30 Fortune","effect":"Spell. Dissonance X (see description). Requires 6 other abilities from the Mantle of Knowledge. You pour oil onto water, inspect bones or livers, read the moon, or some other method of interpreting portents as you seek to gain insight into a question. Ask a question of the GM and choose an Insight value up to your ranks in Magic Arts (minimum zero). The GM will then choose an insight value for the information you’re seeking. Higher insight values provide more information or uncover more hidden knowledge. Low insight values correspond to more easily findable information. Make a Magic Arts Test with the TN equal to 12 plus the insight value you chose. On a Failure, you receive no answer. On a Success, note whether the GM’s insight value or your insight value is higher. If the Insight value you chose is higher than the Insight value chosen by the GM, you have interpreted the elements correctly and the GM answers the question truthfully, though not always in a way that feels immediately useful. If your insight value is lower than the Insight value chosen by the GM, the GM provides a cryptic clue towards the answer—the larger the gap between your insight value and the GM's insight value, the more obscure the clue. On a Dynamic Success, decrease the GM’s insight value by 2— on a Critical Success instead decrease the GM’s insight value by 4. The dissonance of this spell is equal to 3 plus the insight value chosen by the caster. In addition, the Attune action may not be used to mitigate any dissonance from this spell, though Grit damage is reduced by the Dangerous Knowledge ability (this is an exception to the normal rule that Adamant cannot affect Irresistible damage). On a Dynamic Failure you, take twice the Animity damage from the spell."}]},{"id":"mantle-of-nature","label":"Mantle of Nature","items":[{"id":"mantle-of-nature-songs-of-nature","name":"SONGS OF NATURE","page":183,"cost":"10 Fortune","effect":"Spell. Dissonance 1. You intuitively understand communication of non-sapient natural beings. You may ask simple questions, limited to the understanding of the being (a parakitty might know when its owner was last around, while moss is limited to know if its been stepped on recently). You may use Influence and Deception against non-sapient natural beings. You do not need to take the Attune action to resolve the dissonance of this spell until you take an action other than communicate with the natural world."},{"id":"mantle-of-nature-primal-instinct","name":"PRIMAL INSTINCT","page":184,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You gain a sudden hunch about a physical or environmental danger to yourself and how to avoid it. If used in a cinematic, gain +4 defense against an attack (this may be used after your opponent rolls)"},{"id":"mantle-of-nature-the-way-of-things","name":"THE WAY OF THINGS","page":184,"cost":"10 Fortune","effect":"Communing with the natural world has taught you that life is brief, but even the end of life nourishes future life. Gain Adamant 2."},{"id":"mantle-of-nature-sense-of-the-natural-world","name":"SENSE OF THE NATURAL WORLD","page":184,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You gain an intuitive understanding of the ecosystem surrounding you. Gain +2 dice on any Science tests to answer questions about life around you, or Piloting tests to navigate the terrain. This ability does not work in non-natural areas."},{"id":"mantle-of-nature-dangerous-lands-hear-the-call","name":"DANGEROUS LANDS HEAR THE CALL","page":184,"cost":"10 Fortune","effect":"Spell. Interrupt. Dissonance 1. You channel a natural danger against an opponent. Roll Magic Arts against the Aegis of a target within 100m and do damage based on the pre-existing danger in the situation. ※ None (e.g. idyllic peaceful field). Do 1 point of damage as a mild wind blows an object into them, or they twist their ankle on uneven ground. ※ Mild (e.g. a wild forest or mild storm). Do 1d6 damage as ground gives, objects fall, or they are buffeted by a gust of wind. ※ Moderate (e.g. craggy mountains, a large thunderstorm). Do 3d6 damage as lighting strikes, rocks fall, etc. ※ Severe (e.g. a hurricane, a dangerous old growth forest, extreme temperatures). Do 6d6 damage. At the GM's discretion, other hazards may occur instead of direct damage (aggressive animals, falling down holes, being shoved or trapped)"},{"id":"mantle-of-nature-gather-nature-s-dangers","name":"GATHER NATURE’S DANGERS","page":184,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Requires 3 other. abilities from the Mantle of Nature. You increase the natural hazards within 100m of you for 5 Rounds, up to a maximum of Moderate. Use the following scale: ※ None (e.g. idyllic peaceful field). No effect. ※ Mild (e.g. a wild forest or mild storm). Apply a -1 penalty on all relevant tests in the area. ※ Moderate (e.g. craggy mountains, a large thunderstorm). Apply a -3 penalty on all relevant tests in the area. ※ Severe (e.g. a hurricane, a dangerous old growth forest, extreme temperatures). Apply a -5 penalty on all relevant tests in the area."},{"id":"mantle-of-nature-scatter-nature-s-dangers","name":"SCATTER NATURE’S DANGERS","page":184,"cost":"20 Fortune","effect":"Spell. Dissonance 2. Requires 3 other. abilities from the Mantle of Nature. You decrease the risk of natural hazards within 100m around you for 5 Rounds. Decrease the hazards of nature around you by one step on the following scale. ※ None (e.g. idyllic peaceful field). No effect. ※ Mild (e.g. a wild forest or mild storm). Apply a -1 penalty on all relevant tests in the area. ※ Moderate (e.g. craggy mountains, a large thunderstorm). Apply a -3 penalty on all relevant tests in the area. ※ Severe (e.g. a hurricane, a dangerous old growth forest, extreme temperatures). Apply a -5 penalty on all relevant tests in the area."},{"id":"mantle-of-nature-incite-beast","name":"INCITE BEAST","page":184,"cost":"20 Fortune","effect":"Spell. Dissonance 1. Requires 3 other. abilities from the Mantle of Nature. You drive a non-sapient natural animal within 10m into an aggressive rage against a target within 100m. Make an immediate Magic Arts vs Aegis of the animal in question. If the animal is domesticated, the owner may instead make a Piloting Test instead of Aegis. On a Success, the animal becomes hostile against the target and attempts to attack them. On a Dynamic Success, the animal gains +2 dice on any attacks; on a Critical Success the caster additionally can control the actions of the animal. This effect lasts until the end of the scene."},{"id":"mantle-of-nature-dowsing","name":"DOWSING","page":184,"cost":"10 Fortune","effect":"Spell. Dissonance 2. Find a natural object or material relevant to a non-sapient natural being, such as food, water, shelter, or other living beings. Make a Magic Arts Test; the result is the range in kilometers within which the object or material can be found."},{"id":"mantle-of-nature-soothe-beast","name":"SOOTHE BEAST","page":185,"cost":"20 Fortune","effect":"Spell. Dissonance 1. Requires 3 other. abilities from the Mantle of Nature. You drive a non-sentient natural animal within 10m to act peacefully. Make an immediate Magic Arts vs Aegis of the animal in question. If the animal is domesticated, the owner may instead make a Piloting Test instead of Aegis. On a Success, it becomes docile and is treated as having a Regard of 5 to all targets within 100m. If the animal already has a positive Regard to you, increase its Regard to you by 5. This effect lasts for 1 hour."}]},{"id":"mantle-of-secrets","label":"Mantle of Secrets","items":[{"id":"mantle-of-secrets-witness-forgotten-knowledge","name":"WITNESS FORGOTTEN KNOWLEDGE","page":185,"cost":"10 Fortune","effect":"Spell. Dissonance 3. Interrupt. Upon witnessing the loss of knowledge (whether it be through the destruction of a book or device or the death of a being), you may cast this spell. Make a Magic Arts test against TN 10 for inanimate objects, or the Aegis of the dying being. On a Success, you learn any secrets about to be lost as if you had spent an hour inspecting or honestly conversing with the subject. This spell only works on information about to be irrevocably lost—knowledge of which there is a copy or known by someone else cannot be learned by this spell."},{"id":"mantle-of-secrets-elude-notice","name":"ELUDE NOTICE","page":185,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You twist attention away from you or another. Make a Magic Arts test vs Vigilance of a character who you recently lost concealment to. On a Success, increase your Concealment to them by 2."},{"id":"mantle-of-secrets-forget","name":"FORGET","page":185,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Pick a target within 10m (you are a valid target). If you are targeting an unwilling target, roll Magic Arts vs Aegis; otherwise roll vs TN 10. On a Success, you erase all memories of 1 hour of time, or an equivalent amount of facts or knowledge. These memories are inaccessible for 2d6 days. On a Dynamic or Critical Success, you may spend 5 Grit to cause the memories to be permanently erased."},{"id":"mantle-of-secrets-unremarkable-face","name":"UNREMARKABLE FACE","page":185,"cost":"10 Fortune","effect":"Spell. Dissonance 3. You cover yourself with a glamour that draws attention away from yourself and makes you harder to recognize. You gain Resistance 2 against all reductions of concealment in social situations. The glamour persists indefinitely as long as you remain in a group. If you draw individual Concealment to yourself (e.g. attempting to get past a guarded checkpoint alone or by jumping up on a table and dancing), roll Magic Arts vs the highest Vigilance observing you. On a Success the glamour persists and you remain unrecognizable (though they may still react to you); on a Failure the spell ends immediately."},{"id":"mantle-of-secrets-hunter-in-the-dark","name":"HUNTER IN THE DARK","page":186,"cost":"10 Fortune","effect":"Spell. Dissonance 1. Interrupt. You may cast this spell in conjunction with an attack (yours or another’s) against a target within 100m. Roll Magic Arts vs Aegis—on a Success, reduce their Guard and Aegis by 5 until the start of their next turn."},{"id":"mantle-of-secrets-seek-answer","name":"SEEK ANSWER","page":186,"cost":"20 Fortune","effect":"Spell. Dissonance 3. Requires 3 other. abilities from the Mantle of Secrets. You look for knowledge. State a simple question that you do not know the answer to and make a Magic Arts test vs TN 10. If you succeed, you learn of the existence and the location of any object within 100m that could answer your question. If the question could be answered by a person within 100m range, compare your result to their Aegis. If your roll beats their Aegis, you learn of their existence and location."},{"id":"mantle-of-secrets-misdirect","name":"MISDIRECT","page":186,"cost":"20 Fortune","effect":"Spell. Dissonance 1. Interrupt. Requires. 3 other abilities from the Mantle of Secrets. You gain Reliable 3 and Inspired on a Deception test you make in conjunction with this spell."},{"id":"mantle-of-secrets-fade-to-anonymity","name":"FADE TO ANONYMITY","page":186,"cost":"30 Fortune","effect":"Spell. Dissonance 10. Interrupt. Requires 6 other abilities from the Mantle of Secrets. You will the world to ignore you. Gain 3 concealment on any ongoing concealment track, and move all Current Regard towards you 2 points towards zero."}]},{"id":"way-of-earth","label":"Way of Earth","items":[{"id":"way-of-earth-shield-of-earth","name":"SHIELD OF EARTH","page":187,"cost":"10 Fortune","effect":"Meditation. You fill yourself with the solidity and strength of earth to protect yourself from harm. Gain +2 Armor and +5 Maximum Health."},{"id":"way-of-earth-impregnable-self","name":"IMPREGNABLE SELF","page":187,"cost":"10 Fortune","effect":"Meditation. You focus your sense of self into an unbreakable gem, becoming unshakable. Gain Adamant 2 and +5 Maximum Animity."},{"id":"way-of-earth-understanding-of-matter","name":"UNDERSTANDING OF MATTER","page":187,"cost":"10 Fortune","effect":"Meditation. You gain an intuitive control over solid matter. You may shape earth and metal you touch as if it was the consistency of clay. In addition to its creative uses, you may do 3d6 damage ignoring Armor when using this to damage metal or earth structures. For other targets, ignore 2 points of Armor when making Melee Attacks."},{"id":"way-of-earth-force-of-earth","name":"FORCE OF EARTH","page":188,"cost":"10 Fortune","effect":"Meditation. You make yourself harder and denser as you make attacks, increasing the power behind your attacks. Gain Augment 2 on Melee Combat tests."},{"id":"way-of-earth-enduring-meditations","name":"ENDURING MEDITATIONS","page":188,"cost":"10 Fortune","effect":"Your meditation effects last for one week instead of 24 hours. Once per day when meditating for at least 10 minutes you may spend 1 Grit to heal 2 Health and 2 Animity Damage."},{"id":"way-of-earth-mountain-stance","name":"MOUNTAIN STANCE","page":188,"cost":"10 Fortune","effect":"Requires 3 other Way of Earth. paradigm abilities. When you take the defend Backup Action, Melee Combat attacks you make until the end of your next turn gain Augment 3."},{"id":"way-of-earth-stone-s-timeless-reserve","name":"STONE’S TIMELESS RESERVE","page":188,"cost":"20 Fortune","effect":"Meditation. Requires 2 meditations. from the Way of Earth. Gain +4 Aegis."},{"id":"way-of-earth-scholars-of-the-object-s-form","name":"SCHOLARS OF THE OBJECT'S FORM","page":188,"cost":"10 Fortune","effect":"You gain Reliable 3 on all Tech and Arts tests to build or repair objects."},{"id":"way-of-earth-unyielding-earth","name":"UNYIELDING EARTH","page":188,"cost":"20 Fortune","effect":"Requires 2 meditations from the Way. of Earth. While you have a meditation active and are hit by an attack that would do damage, you may spend 1 Grit as an Interrupt Action to roll Magic Arts. If the result is higher than the roll that hits you, you take no damage."},{"id":"way-of-earth-endurance-of-ancient-mountains","name":"ENDURANCE OF ANCIENT MOUNTAINS","page":188,"cost":"30 Fortune","effect":"Meditation. Requires 4 meditations. from the Way of Earth. Whenever you take damage to Health or Animity, you may spend any amount of Grit. Reduce damage by 4 per Grit spent."}]},{"id":"way-of-water","label":"Way of Water","items":[{"id":"way-of-water-one-with-water","name":"ONE WITH WATER","page":188,"cost":"10 Fortune","effect":"Meditation. You can breathe water as air, and gain +2d6 on all physicality tests related to swimming."},{"id":"way-of-water-water-whip","name":"WATER WHIP","page":188,"cost":"10 Fortune","effect":"Meditation. While this meditation is active, when making a Melee Attack, you may replace your Melee Combat skill with Magic Arts to target anyone within 10m. If you hit, instead of doing damage, you may move you and your target any distance towards each other and your target is Grappled (see \"Grapple\" on pg 57), requiring them to make an opposed Melee Combat or Physicality test vs your Magic Arts skill as a Main Action in order to move. If you move or make another attack, the Grappled condition ends."},{"id":"way-of-water-purify","name":"PURIFY","page":188,"cost":"10 Fortune","effect":"Meditation. You gain +4 Aegis and Guard against poison effects. You may remove any impurities out of water you touch, making it potable and refreshing. You may heal any poison or other metabolic effects or damage on a touched target by making a Magic Arts Test vs the TN of the poison. On a Success any lingering effects are removed; on a Dynamic Success heal up to 5 damage done by the effect. On a Critical Success instead heal up to 10 damage from the effect. A target may only benefit from healing once per effect."},{"id":"way-of-water-calm-mind","name":"CALM MIND","page":189,"cost":"10 Fortune","effect":"Meditation. You gain Adamant +2, and whenever you spend Grit to negate Animity damage, you gain an equal amount of temporary Grit that lasts until the end of your next turn before being lost."},{"id":"way-of-water-fluid-meditations","name":"FLUID MEDITATIONS","page":189,"cost":"10 Fortune","effect":"You may spend 2 Grit as a Main Action to change a meditation to another meditation."},{"id":"way-of-water-flowing-stance","name":"FLOWING STANCE","page":189,"cost":"10 Fortune","effect":"Requires 3 other Way of Water. paradigm abilities. Whenever you are attacked, you may immediately spend 1 Grit to take the Focus Backup Action."},{"id":"way-of-water-scholars-of-the-body","name":"SCHOLARS OF THE BODY","page":189,"cost":"10 Fortune","effect":"You gain Reliable 3 on all Science tests related to medicine."},{"id":"way-of-water-go-with-the-flow","name":"GO WITH THE FLOW","page":189,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of Water. Whenever you take 5 or more damage (after all other effects), you take 3 less damage, to a minimum of one."},{"id":"way-of-water-powerful-current","name":"POWERFUL CURRENT","page":189,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of Water Whenever you get a Dynamic or Critical Success with an unarmed attack, you may move the target 5m in a direction of your choice."},{"id":"way-of-water-redirected-effort","name":"REDIRECTED EFFORT","page":189,"cost":"20 Fortune","effect":"Requires Fluid Mediations and 2 other. abilities from the Way of Water. You may change meditations whenever you spend Grit."},{"id":"way-of-water-an-ocean-shall-refill","name":"AN OCEAN SHALL REFILL","page":189,"cost":"30 Fortune","effect":"Meditation. Requires 4 other. meditations from the Way of Water. You roll one additional dice on Grit tests (keep 3 total). On a Dynamic Success on a Grit Test, heal 5 Health and Animity damage. On a Critical Success, heal 10 Health and Animity damage and remove a Consequence."}]},{"id":"way-of-fire","label":"Way of Fire","items":[{"id":"way-of-fire-focus-into-intent","name":"FOCUS INTO INTENT","page":190,"cost":"10 Fortune","effect":"You may end a Meditation to roll +1d6 on a Test and treat the Test as Inspired."},{"id":"way-of-fire-soul-of-fire","name":"SOUL OF FIRE","page":190,"cost":"10 Fortune","effect":"Meditation. Whenever you trigger an Impulse, gain an additional +2 Grit. You gain Adamant 1."},{"id":"way-of-fire-explosive-burst","name":"EXPLOSIVE BURST","page":190,"cost":"10 Fortune","effect":"Meditation. You may spend 2 Grit on a turn to gain Augment 2 and +1 Backup Action. End this Meditation."},{"id":"way-of-fire-perilous-target","name":"PERILOUS TARGET","page":190,"cost":"10 Fortune","effect":"Meditation. Whenever you take Health or Animity damage, you may spend 1 Grit. If you do, the target takes 1d6 damage of the same type."},{"id":"way-of-fire-burning-touch","name":"BURNING TOUCH","page":190,"cost":"10 Fortune","effect":"Meditation. Your unarmed attacks do 2d6 + Brawn fire damage. You may end this meditation to make a Magic Arts test vs Aegis of all targets within 1m. On a Success, do 3d6 fire damage to each target."},{"id":"way-of-fire-ashes-of-the-phoenix","name":"ASHES OF THE PHOENIX","page":190,"cost":"10 Fortune","effect":"Meditation. Whenever you succeed on a Grit Test, gain +2 Health, Animity, and Grit."},{"id":"way-of-fire-wildfire-stance","name":"WILDFIRE STANCE","page":190,"cost":"10 Fortune","effect":"Requires 3 other Way of Fire. paradigm abilities. Once per turn when you do damage to a target with a Melee Attack, you may spend 3 Grit to move up to 3m and make an immediate additional Melee Attack against a different target."},{"id":"way-of-fire-scholars-of-the-heart","name":"SCHOLARS OF THE HEART","page":191,"cost":"10 Fortune","effect":"You may take 2 Irresistible Animity damage to gain +1d6 and Inspired on an Arts test."},{"id":"way-of-fire-wildfire-burns","name":"WILDFIRE BURNS","page":191,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of Fire. Whenever you make a Dynamic or Critical Success against an opponent, you may choose to give them a Consequence in addition to the normal effect of the Dynamic or Critical Success. If you do, the GM gains 3 Grit."},{"id":"way-of-fire-eager-spark","name":"EAGER SPARK","page":191,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of Fire. You gain +6 initiative, and gain Augment 3 on the first Round of a cinematic."},{"id":"way-of-fire-rekindled-meditation","name":"REKINDLED MEDITATION","page":191,"cost":"20 Fortune","effect":"Requires 3 other abilities from the Way. of Fire. If you have used an effect that ends a meditation since the start of your last turn, you may take a Backup Action and spend 1 Grit to make a TN 12 Magic Arts test. If you succeed, at the end of your next turn the meditation becomes active again."},{"id":"way-of-fire-body-of-fire","name":"BODY OF FIRE","page":191,"cost":"30 Fortune","effect":"Meditation. Requires 4 other. meditations from the Way of Fire. Your eyes flicker with flame, and your body is warm to the touch, erupting at your will. You gain 20 Armor against all fire damage. You may spend 3 Grit as an interrupt to make a Magic Arts vs Aegis test against a target within T range. On a Success, they take 3d6 Fire Damage."}]},{"id":"way-of-air","label":"Way of Air","items":[{"id":"way-of-air-flickering-meditation","name":"FLICKERING MEDITATION","page":191,"cost":"10 Fortune","effect":"You may spend a Backup Action to gain the effects of a meditation until the end of your next turn."},{"id":"way-of-air-meditation-of-movement","name":"MEDITATION OF MOVEMENT","page":191,"cost":"10 Fortune","effect":"Meditation. You may spend 1 Grit to take the Focus action (see pg 34) as a Free Action whenever you take the Minor Move (pg 34) action."},{"id":"way-of-air-light-body","name":"LIGHT BODY","page":192,"cost":"10 Fortune","effect":"Meditation. Gain +1d6 on all Physicality tests related to movement. When you take the Major Move action (see pg 33) under your own power you gain Acceleration 3. While able to freely move, you take no damage from falling, and may always land on your feet."},{"id":"way-of-air-float-like-a-butterfly","name":"FLOAT LIKE A BUTTERFLY","page":192,"cost":"10 Fortune","effect":"Meditation. Gain +2 Guard. As an Interrupt Action, you may spend 1 Grit to increase your physical Armor by 3 for one attack."},{"id":"way-of-air-supernatural-leaps","name":"SUPERNATURAL LEAPS","page":192,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of Air. You may use Magic Arts in lieu of Physicality for tests related to moving quickly (such as chases). When moving you may jump over any intervening obstacles, ignoring gaps and difficult terrain without making a Test. You may move in any direction, as long as there is a solid place to land on."},{"id":"way-of-air-eye-of-the-hurricane","name":"EYE OF THE HURRICANE","page":192,"cost":"10 Fortune","effect":"You gain +5 Adamant and +3 on all defenses until the start of your next turn on any turn you take no actions besides move. If you took no actions besides a Major or Minor Move in your last turn, you may spend 1 Grit as an Interrupt Action in response to an attack, if you do you may roll Magic Arts and replace your guard with the result if higher."},{"id":"way-of-air-soaring-stance","name":"SOARING STANCE","page":192,"cost":"10 Fortune","effect":"Requires 2 other meditations from the. Way of Air. If you take a Minor Move action before a Melee Attack, you gain Augment 2 on that attack. If you take a Minor Move after an attack, you gain +1 guard until the end of your next turn."},{"id":"way-of-air-scholars-of-the-stars-and-time","name":"SCHOLARS OF THE STARS AND TIME","page":192,"cost":"10 Fortune","effect":"You gain Reliable 3 on all Science tests related to Astronomy, and Humanities tests related to History."},{"id":"way-of-air-whirling-strikes","name":"WHIRLING STRIKES","page":192,"cost":"20 Fortune","effect":"Meditation. Requires 3 other abilities. from the Way of Air. After taking a Main Action, you may spend 1 Grit to move 10m."},{"id":"way-of-air-become-the-wind","name":"BECOME THE WIND","page":192,"cost":"30 Fortune","effect":"Meditation. Requires 4 other. meditations from the Way of Air. You gain a max Speed of 3. When you are hit by an attack that is a normal Success, you may spend 2 Grit to negate that attack. If you do not take a movement action on your next turn after negating an attack, end this meditation."}]},{"id":"way-of-the-void","label":"Way of the Void","items":[{"id":"way-of-the-void-emptiness-of-mind","name":"EMPTINESS OF MIND","page":192,"cost":"10 Fortune","effect":"Meditation. Gain 1 maximum Grit. You may spend a Main Action to change this meditation to another meditation."},{"id":"way-of-the-void-imperturbable-core","name":"IMPERTURBABLE CORE","page":192,"cost":"10 Fortune","effect":"Meditation. You gain +4 on all Grit tests. If you get a Dynamic or Critical Success on a Grit Test, you lose the Consequence you gained for dropping to zero Grit."},{"id":"way-of-the-void-potentiality","name":"POTENTIALITY","page":193,"cost":"10 Fortune","effect":"Meditation. After you roll, you may spend 1 Grit to make that roll Inspired."},{"id":"way-of-the-void-beneath-notice","name":"BENEATH NOTICE","page":193,"cost":"10 Fortune","effect":"When you are remaining perfectly stationary, you may make a Magic Arts test. Your result becomes the TN to notice you. This effect may fail if you find yourself in a position that can't help but draw attention to yourself (e.g. standing in a doorway someone is going through)"},{"id":"way-of-the-void-fill-the-void","name":"FILL THE VOID","page":193,"cost":"10 Fortune","effect":"Meditation. You may, as a Backup Action, make a Magic Arts vs Aegis test against all enemies within 50m. On a Success, they are moved 10m towards you."},{"id":"way-of-the-void-empty-stance","name":"EMPTY STANCE","page":193,"cost":"10 Fortune","effect":"Requires 3 other Way of the Void. paradigm abilities. When you take the Hold Action for a Melee Attack in response to an enemy's action, you may move up to 3m as part of the Melee Attack and gain Augment 5 on the attack."},{"id":"way-of-the-void-scholars-of-ignorance","name":"SCHOLARS OF IGNORANCE","page":193,"cost":"10 Fortune","effect":"You gain Reliable 3 on all untrained skills."},{"id":"way-of-the-void-empty-space","name":"EMPTY SPACE","page":193,"cost":"20 Fortune","effect":"Interrupt. Requires 3 other abilities. from the Way of the Void. You may spend 1 Grit to use this ability as an interrupt. If you do you may take no actions on your next turn but gain Adamant 5 and +5 Aegis and Vigilance until you take another action."},{"id":"way-of-the-void-nullify","name":"NULLIFY","page":193,"cost":"20 Fortune","effect":"Meditation. Requires 2 other. meditations from the Way of the Void. As a Main Action, you may make an Magic Arts test opposed by the casting skill of the opposing caster. On a Success, you end a spell effect within 50m that they initiated. The opposing caster gets a +2 for each bar or point of dissonance involved to cast the spell."},{"id":"way-of-the-void-void-body","name":"VOID BODY","page":193,"cost":"30 Fortune","effect":"Meditation. Requires 4 other. meditations from the Way of the Void. You may spend 1 Grit as a Backup Action to become partially insubstantial until the end of your next turn. You may move through any barrier less than 1 foot deep, and may ignore gravity while insubstantial. You gain +4 on all physicality tests related to stealth while partially insubstantial. While partially insubstantial, you take and inflict half as much physical damage."},{"id":"way-of-the-void-empty-the-void","name":"EMPTY THE VOID","page":193,"cost":"20 Fortune","effect":"Meditation. Requires Fill the Void and 2 other meditations from the Way of the Void. As a Main Action, make a Magic Arts vs Aegis test against all creatures of your choice within 50m. On a Success, they move 10m away from you and take 2d6 physical damage."}]}]};
